/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"RL-001":{"cognitivo":{"motivo":"Cobrar a contrapositiva, a equivalência mais explorada pela banca em lógica.","palavraCritica":"não confia → não cumpre"},"comentario":{"resolucao":"CERTO. P→Q é logicamente equivalente à sua contrapositiva ~Q→~P: ambas possuem a mesma tabela-verdade. A assertiva negou o consequente e o transformou em antecedente, negando também o antecedente original.","fundamento":"Lógica proposicional — equivalências notáveis do condicional.","macete":"Equivalências do 'se... então': INC (Inverte e Nega os dois) ou troca por 'ou' negando o primeiro (~P∨Q).","erroComum":"Aceitar a recíproca Q→P como equivalente — a banca cobra essa confusão com frequência.","comoBancaPensa":"Veste a estrutura lógica com contexto policial para disfarçar que a questão é pura tabela-verdade."}},"RL-002":{"cognitivo":{"motivo":"Negação de proposição categórica universal — clássico absoluto da banca.","palavraCritica":"nenhum"},"comentario":{"resolucao":"ERRADO. A negação de “todos os investigados foram indiciados” é “pelo menos um investigado não foi indiciado” (ou “algum investigado não foi indiciado”). “Nenhum foi indiciado” é a proposição contrária, não a contraditória.","fundamento":"Lógica de primeira ordem — quadrado lógico das oposições.","macete":"Para negar, basta UM contraexemplo: 'algum não'.","erroComum":"Responder com o extremo oposto em vez da contraditória mínima.","comoBancaPensa":"Explora a intuição leiga de que o oposto de 'todos' é 'nenhum'."}},"RL-003":{"cognitivo":{"motivo":"Aplicação direta das Leis de De Morgan, item expresso do edital (11.4).","palavraCritica":"e (deveria virar ou)"},"comentario":{"resolucao":"ERRADO. Pelas Leis de De Morgan, a negação de uma conjunção é a disjunção das negações: “O suspeito não estava armado OU não fugiu do local”. Manter o 'e' produz proposição que não é a contraditória.","fundamento":"Leis de De Morgan (lógica proposicional).","macete":"Basta um dos fatos falhar para a conjunção ser falsa — por isso a negação usa OU.","erroComum":"Negar apenas as proposições simples sem trocar o conectivo.","comoBancaPensa":"O item parece 'quase certo' — é o padrão de troca mínima aplicado à lógica."}},"RL-004":{"cognitivo":{"motivo":"Regra nuclear da tabela-verdade do condicional.","palavraCritica":"V → F"},"comentario":{"resolucao":"CERTO. O condicional P→Q assume valor falso exclusivamente na combinação P verdadeiro e Q falso; nas demais três linhas da tabela-verdade, é verdadeiro.","fundamento":"Tabela-verdade do conectivo condicional.","macete":"Promessa: só é descumprida quando a condição aconteceu e o prometido não veio.","erroComum":"Achar que antecedente falso torna o condicional falso.","comoBancaPensa":"Planta um 'somente' verdadeiro para punir o atalho cego — o mesmo padrão de DP-004."}},"RL-005":{"cognitivo":{"motivo":"Percentuais sucessivos sobre bases diferentes — armadilha aritmética recorrente.","palavraCritica":"sobre o novo montante"},"comentario":{"resolucao":"ERRADO. Com valor inicial V: após +20%, tem-se 1,2V; o desconto de 20% incide sobre 1,2V, resultando 1,2V × 0,8 = 0,96V. Há redução de 4% em relação ao original.","fundamento":"Matemática básica — variações percentuais sucessivas.","macete":"x% para cima e x% para baixo = perde (x²/100)%. Com 20: perde 4%.","erroComum":"Somar percentuais de bases distintas.","comoBancaPensa":"Aposta na aritmética intuitiva (+20−20=0) contra a multiplicativa correta."}},"RL-006":{"cognitivo":{"motivo":"Princípio fundamental da contagem com restrição de não repetição.","palavraCritica":"distintos"},"comentario":{"resolucao":"CERTO. Para o 1º algarismo há 10 opções; para o 2º, 9 (não pode repetir); para o 3º, 8. Pelo princípio multiplicativo: 10×9×8 = 720 senhas.","fundamento":"Princípios de contagem — arranjo simples A(10,3).","macete":"Leia SEMPRE se há 'distintos/sem repetição' antes de multiplicar.","erroComum":"Calcular 10³ = 1000 por desatenção à restrição.","comoBancaPensa":"O número é o ponto de checagem: conferir a conta é obrigatório antes de julgar."}},"RL-007":{"cognitivo":{"motivo":"Cobrar a equivalência entre condicional e sua contrapositiva.","palavraCritica":"~Q → ~P"},"comentario":{"resolucao":"CERTO. A condicional P→Q é logicamente equivalente à sua contrapositiva ~Q→~P. Aqui: P='há indícios', Q='inquérito instaurado'. A contrapositiva 'se não instaurado, então não há indícios' preserva o valor lógico.","fundamento":"Lógica proposicional — equivalências da condicional.","macete":"P→Q também equivale a ~P ∨ Q. A recíproca Q→P e a inversa ~P→~Q não equivalem à original.","erroComum":"Aceitar a recíproca como equivalente.","comoBancaPensa":"Condicional × contrapositiva × recíproca é a tríade favorita de equivalência."}},"RL-008":{"cognitivo":{"motivo":"Cobrar a negação correta da condicional (P ∧ ~Q).","palavraCritica":"P e não Q"},"comentario":{"resolucao":"CERTO. A negação de uma condicional P→Q é P ∧ ~Q (o antecedente ocorre e o consequente não). Logo: 'O agente cumpriu o mandado E o suspeito NÃO foi preso'. A negação não é outra condicional.","fundamento":"Lógica proposicional — negação da condicional.","macete":"Para negar 'se chove, levo guarda-chuva': 'choveu E não levei'.","erroComum":"Negar mantendo 'se...então' ou negando os dois termos.","comoBancaPensa":"Negação de condicional é das mais cobradas — a resposta nunca é outra condicional."}},"RL-009":{"cognitivo":{"motivo":"Cobrar a negação correta do quantificador universal.","palavraCritica":"Nenhum (deveria ser 'Pelo menos um não')"},"comentario":{"resolucao":"ERRADO. A negação de 'Todos os policiais são armados' é 'Pelo menos um policial não é armado' (existe policial não armado). 'Nenhum policial é armado' é a contrária, não a negação (basta um contraexemplo para negar o 'todos').","fundamento":"Lógica quantificacional — negação de proposições categóricas.","macete":"Para derrubar 'todos', basta UM que não seja. Não precisa que 'nenhum' seja.","erroComum":"Trocar a negação pelo oposto extremo ('nenhum').","comoBancaPensa":"Negar quantificador universal com 'nenhum' é a pegadinha mais recorrente do tema."}},"RL-010":{"cognitivo":{"motivo":"Cobrar a aplicação das Leis de De Morgan.","palavraCritica":"nega os dois e troca 'e' por 'ou'"},"comentario":{"resolucao":"CERTO. Lei de De Morgan: a negação de uma conjunção (P ∧ Q) é a disjunção das negações (~P ∨ ~Q). Logo, negar 'culpado E lícita' = 'não culpado OU não lícita'.","fundamento":"Lógica proposicional — Leis de De Morgan.","macete":"Negou 'e'? Vira 'ou' (e nega as partes). Negou 'ou'? Vira 'e'.","erroComum":"Manter o conectivo ou negar apenas um termo.","comoBancaPensa":"De Morgan é cobrado direto ou embutido na negação de proposições compostas."}},"RL-011":{"cognitivo":{"motivo":"Cobrar o cálculo de probabilidade condicional em espaço amostral reduzido.","palavraCritica":"dado que é figura → universo = 12"},"comentario":{"resolucao":"CERTO. Há 12 figuras (4 valetes, 4 damas, 4 reis). Condicionada a ser figura, a probabilidade de ser rei é P(rei | figura) = 4/12 = 1/3. O universo reduz-se às 12 figuras, não às 52 cartas.","fundamento":"Teoria da probabilidade — probabilidade condicional P(A|B).","macete":"'Dado que' = reduza o denominador ao evento já conhecido.","erroComum":"Calcular 4/52 (ignorando a condição).","comoBancaPensa":"Condicional é cobrada para testar se o candidato reduz corretamente o espaço amostral."}},"RL-012":{"cognitivo":{"motivo":"Cobrar a validade do modus tollens.","palavraCritica":"nega o consequente → nega o antecedente"},"comentario":{"resolucao":"CERTO. O argumento tem a forma modus tollens: de P→Q e ~Q, conclui-se ~P. É uma forma de argumento válida. (Cuidado: 'P→Q, ~P ⊢ ~Q' seria a falácia da negação do antecedente, inválida.)","fundamento":"Lógica — regras de inferência (modus tollens).","macete":"Ponens: afirma a causa → afirma o efeito. Tollens: nega o efeito → nega a causa. Ambos válidos.","erroComum":"Confundir com a negação do antecedente (falácia).","comoBancaPensa":"Formas válidas × falácias formais são o alvo em lógica de argumentação."}},"RL-013":{"cognitivo":{"motivo":"Cobrar o termo geral da PA.","palavraCritica":"a_n = a1 + (n−1)·r"},"comentario":{"resolucao":"CERTO. Termo geral da PA: a_n = a1 + (n−1)·r. Com a1=3, r=5 e n=10: a10 = 3 + (10−1)·5 = 3 + 45 = 48.","fundamento":"Matemática — progressão aritmética (termo geral).","macete":"a10 = a1 + 9r (nove 'saltos' de razão, não dez).","erroComum":"Usar 10·r (esquecendo o n−1) e obter 53.","comoBancaPensa":"O erro clássico é o (n−1); a banca calibra o número para punir esse deslize."}},"RL-014":{"cognitivo":{"motivo":"Distinguir arranjo (ordem importa) de combinação (ordem não importa).","palavraCritica":"sem cargos definidos = ordem irrelevante"},"comentario":{"resolucao":"CERTO. Como a comissão não tem cargos (a ordem dos escolhidos não altera o resultado), aplica-se a COMBINAÇÃO: C(5,3) = 5!/(3!·2!) = 10 comissões possíveis. Se houvesse cargos distintos (presidente, secretário...), seria arranjo.","fundamento":"Análise combinatória — arranjo × combinação.","macete":"Tem cargo/ordem? Arranjo. Não tem? Combinação.","erroComum":"Usar arranjo (ordem) para uma comissão sem hierarquia.","comoBancaPensa":"A relevância da ordem é o divisor cobrado entre arranjo e combinação."}},"RL-015":{"cognitivo":{"motivo":"Cobrar o princípio da inclusão-exclusão em conjuntos.","palavraCritica":"n(A∪B) = n(A) + n(B) − n(A∩B)"},"comentario":{"resolucao":"CERTO. n(A∪B) = n(A) + n(B) − n(A∩B) = 60 + 50 − 30 = 80 usam pelo menos uma rede. Logo, 100 − 80 = 20 não usam nenhuma das duas.","fundamento":"Teoria dos conjuntos — princípio da inclusão-exclusão.","macete":"União = soma das partes menos a interseção. Sempre desconte a dupla contagem.","erroComum":"Somar 60+50=110 e ignorar a interseção.","comoBancaPensa":"A dupla contagem da interseção é o erro que a banca busca."}},"RL-016":{"cognitivo":{"motivo":"Cobrar que variações percentuais sucessivas não se cancelam por soma.","palavraCritica":"1,10 × 0,90 = 0,99"},"comentario":{"resolucao":"ERRADO. As variações sucessivas multiplicam-se: 1,10 × 0,90 = 0,99. O valor final é 99% do original — uma redução líquida de 1%, e não o retorno ao valor inicial. Porcentagens sucessivas não se somam algebricamente.","fundamento":"Matemática financeira/básica — variações percentuais sucessivas.","macete":"+10% depois −10% = ×1,10×0,90 = 0,99 (perde 1%).","erroComum":"Somar +10% e −10% e concluir 'volta ao mesmo'.","comoBancaPensa":"A intuição de somar percentuais é a armadilha explorada."}},"RL-017":{"cognitivo":{"motivo":"Cobrar a diferença entre negar e afirmar o contrário/oposto.","palavraCritica":"negar = 'não é', não 'é outra coisa'"},"comentario":{"resolucao":"ERRADO. A negação de 'João é policial' é 'João NÃO é policial'. Dizer que 'João é bombeiro' é uma proposição diferente, não a negação lógica da original (João poderia não ser policial nem bombeiro).","fundamento":"Lógica proposicional — negação.","macete":"Negar = colocar 'não'. Não é trocar por outra categoria.","erroComum":"Negar afirmando um oposto arbitrário.","comoBancaPensa":"Confunde negação lógica com afirmação de conteúdo contrário."}},"RL-018":{"cognitivo":{"motivo":"Cobrar a tabela-verdade da disjunção inclusiva.","palavraCritica":"basta uma verdadeira"},"comentario":{"resolucao":"ERRADO. A disjunção inclusiva 'p ou q' é verdadeira quando AO MENOS UMA das proposições é verdadeira; só é falsa quando ambas são falsas. Exigir as duas verdadeiras é característica da CONJUNÇÃO ('p e q').","fundamento":"Lógica proposicional — disjunção inclusiva (tabela-verdade).","macete":"'ou' basta uma. 'e' precisa das duas.","erroComum":"Aplicar à disjunção a regra da conjunção.","comoBancaPensa":"Troca a condição de verdade de 'ou' pela de 'e'."}},"RL-019":{"cognitivo":{"motivo":"Cobrar a tabela-verdade da condicional.","palavraCritica":"antecedente falso → condicional VERDADEIRA"},"comentario":{"resolucao":"ERRADO. A condicional p→q é FALSA apenas quando p é verdadeira e q é falsa. Se o antecedente p é falso, a condicional é VERDADEIRA (verdade vacuosa), qualquer que seja q.","fundamento":"Lógica proposicional — condicional (tabela-verdade).","macete":"Só 'V→F' é falsa. Antecedente falso → sempre verdadeira.","erroComum":"Achar que antecedente falso derruba a condicional.","comoBancaPensa":"Inverte a única linha em que a condicional é falsa."}},"RL-020":{"cognitivo":{"motivo":"Cobrar o conceito de equivalência lógica (mesma tabela-verdade).","palavraCritica":"quantidade de conectivos (irrelevante)"},"comentario":{"resolucao":"ERRADO. Duas proposições são logicamente equivalentes quando têm a MESMA tabela-verdade (mesmos valores lógicos em todas as linhas), e não pela quantidade de conectivos. Ex.: 'p → q' equivale a '~p ∨ q', embora tenham estruturas diferentes.","fundamento":"Lógica proposicional — equivalência lógica.","macete":"Equivalência = mesma tabela-verdade, não mesma 'aparência'.","erroComum":"Definir equivalência por número de conectivos.","comoBancaPensa":"Troca o critério (valor de verdade) por um sintático irrelevante."}},"RL-021":{"cognitivo":{"motivo":"Aplicar o modus tollens a proposições de um caso concreto.","palavraCritica":"nega o consequente → nega o antecedente"},"comentario":{"resolucao":"CERTO. Seja A = “o documento foi assinado” e C = “o processo foi concluído”. O Servidor I afirma A → C; o Servidor II afirma ~C. Pelo modus tollens, conclui-se ~A: o documento não foi assinado. A inferência é válida.","fundamento":"Lógica proposicional — modus tollens.","macete":"Negou o consequente? Nega o antecedente. Sempre válido.","erroComum":"Confundir com a falácia da negação do antecedente.","comoBancaPensa":"Encadeia proposições de um caso e pede a conclusão válida."}},"RL-022":{"cognitivo":{"motivo":"Encadear modus tollens e silogismo disjuntivo.","palavraCritica":"A ∨ P, com ~A → P"},"comentario":{"resolucao":"CERTO. Do modus tollens (I e II) conclui-se que o documento NÃO foi assinado (~A). O Servidor III afirma a disjunção A ∨ P (“assinado ou prazo prorrogado”), que é verdadeira. Sendo A falsa, pelo silogismo disjuntivo P é necessariamente verdadeira: o prazo foi prorrogado.","fundamento":"Lógica proposicional — modus tollens e silogismo disjuntivo.","macete":"Disjunção verdadeira com um lado falso obriga o outro a ser verdadeiro.","erroComum":"Não encadear as duas inferências.","comoBancaPensa":"Cobra raciocínio em duas etapas sobre o mesmo conjunto de declarações."}},"RL-023":{"cognitivo":{"motivo":"Cobrar que a negação de uma condicional não é outra condicional.","palavraCritica":"negação = A ∧ ~C (conjunção)"},"comentario":{"resolucao":"ERRADO. A negação de uma condicional A → C é a CONJUNÇÃO A ∧ ~C. Assim, a negação correta seria: “O documento foi assinado E o processo não foi concluído”. A proposição apresentada continua sendo uma condicional, e não a negação da original.","fundamento":"Lógica proposicional — negação da condicional.","macete":"Negação de condicional nunca é outra condicional: vira 'e'.","erroComum":"Negar apenas o consequente, mantendo o 'se...então'.","comoBancaPensa":"Oferece uma condicional parecida como se fosse a negação."}},"RL-024":{"cognitivo":{"motivo":"Cobrar o cálculo de divisão proporcional direta.","palavraCritica":"R$ 18.000"},"comentario":{"resolucao":"CERTO. Somando as partes (4+5+6=15) e dividindo o total pelo número de partes (45.000/15=3.000), cada 'parte' vale R$ 3.000. O policial com 6 anos recebe 6×3.000 = R$ 18.000.","fundamento":"Matemática — razão e proporção (divisão proporcional direta).","macete":"Some as partes, divida o total, multiplique pela parte desejada.","erroComum":"Dividir o valor igualmente entre os três (erro de dividir sem proporcionalidade).","comoBancaPensa":"Cobra o procedimento completo de divisão em partes diretamente proporcionais."}},"RL-025":{"cognitivo":{"motivo":"Cobrar o cálculo de variação percentual.","palavraCritica":"superior a 20%, porém inferior a 30%"},"comentario":{"resolucao":"CERTO. O aumento absoluto foi de R$ 62,50 (312,50−250). Dividindo pelo valor inicial: 62,50/250 = 0,25 = 25%, valor que está entre 20% e 30%.","fundamento":"Matemática — porcentagem (variação percentual).","macete":"Sempre divida a variação pelo valor INICIAL, nunca pelo final.","erroComum":"Usar o valor final como base do cálculo percentual.","comoBancaPensa":"Item clássico de cálculo percentual com faixa de valores."}},"RL-026":{"cognitivo":{"motivo":"Cobrar a soma de probabilidades de eventos mutuamente exclusivos.","palavraCritica":"1/2"},"comentario":{"resolucao":"CERTO. Total de bolas: 10. Bolas azuis ou verdes: 3+2=5. Probabilidade: 5/10 = 1/2.","fundamento":"Matemática — probabilidade (eventos mutuamente exclusivos).","macete":"P(A ou B) = (casos de A + casos de B) / total, quando A e B são mutuamente exclusivos.","erroComum":"Multiplicar as probabilidades individuais em vez de somar os casos favoráveis.","comoBancaPensa":"Item de fixação sobre a regra da soma em probabilidade."}},"RL-027":{"cognitivo":{"motivo":"Cobrar o cálculo de combinação com restrição de composição.","palavraCritica":"40"},"comentario":{"resolucao":"ERRADO. C(3,2)=3 (mulheres) e C(5,2)=10 (homens); o total de comissões é 3×10=30, e não 40 como afirmado.","fundamento":"Matemática — análise combinatória (combinação simples com restrição).","macete":"Multiplique as combinações de cada grupo restrito separadamente.","erroComum":"Somar em vez de multiplicar as combinações parciais, ou errar um dos cálculos de C(n,p).","comoBancaPensa":"Troca o resultado correto por um número numericamente próximo e plausível."}},"RL-028":{"cognitivo":{"motivo":"Cobrar a regra de negação da proposição condicional.","palavraCritica":"P ∧ ~Q"},"comentario":{"resolucao":"CERTO. A negação de uma condicional 'P → Q' é logicamente equivalente a 'P ∧ ~Q': afirma-se o antecedente (o suspeito confessou) e nega-se o consequente (não será indiciado).","fundamento":"Lógica proposicional — negação de proposições condicionais.","macete":"Negação de 'se P, então Q' = 'P e não Q'.","erroComum":"Negar ambos os termos ('~P → ~Q') ou inverter a condicional.","comoBancaPensa":"Cobra a equivalência lógica mais clássica e mais recorrente em provas CEBRASPE."}},"RL-029":{"cognitivo":{"motivo":"Cobrar a regra correta de negação de proposições universais afirmativas.","palavraCritica":"Nenhum policial"},"comentario":{"resolucao":"ERRADO. A negação de 'Todo policial aprovado realizou o curso de formação' é 'Algum policial aprovado não realizou o curso de formação', e não 'Nenhum policial aprovado realizou o curso' — esta última é a proposição contrária, logicamente distinta da negação (contraditória).","fundamento":"Lógica proposicional — negação de proposições categóricas (quadro de oposições).","macete":"Negação de 'todo é' = 'algum não é'. Nunca 'nenhum é'.","erroComum":"Confundir a proposição contraditória (negação) com a contrária.","comoBancaPensa":"Um dos erros mais recorrentes e mais cobrados pela banca em lógica categórica."}},"RL-030":{"cognitivo":{"motivo":"Cobrar a aplicação do critério de divisibilidade por 11.","palavraCritica":"múltiplo de 11"},"comentario":{"resolucao":"CERTO. Numerando da direita para a esquerda: posições ímpares somam 2+0+1=3; posições pares somam 8+8+9=25. A diferença (3−25=−22) é múltiplo de 11. Conferindo: 918.082 ÷ 11 = 83.462, divisão exata.","fundamento":"Matemática — critérios de divisibilidade (regra do 11).","macete":"Alterne os algarismos (soma ímpares − soma pares); se der múltiplo de 11 (inclusive 0), é divisível.","erroComum":"Numerar os algarismos da esquerda para a direita, invertendo o resultado.","comoBancaPensa":"Cobra a aplicação literal e cuidadosa do critério, com verificação numérica real."}},"RL-031":{"cognitivo":{"motivo":"Cobrar o raciocínio de regra de três composta (produtividade constante).","palavraCritica":"60 laudos ... 6 dias"},"comentario":{"resolucao":"CERTO. A taxa de produtividade é 50 laudos / (10 escrivães × 4 dias) = 1,25 laudos por pessoa-dia. Para 8 escrivães em 6 dias (48 pessoa-dias): 48 × 1,25 = 60 laudos, exatamente como afirmado.","fundamento":"Matemática — regra de três composta (grandezas diretamente proporcionais).","macete":"Calcule a taxa por unidade combinada (pessoa-dia) e multiplique pelo novo total.","erroComum":"Aplicar regra de três simples ignorando uma das variáveis (número de escrivães ou de dias).","comoBancaPensa":"Testa o raciocínio proporcional composto com dois fatores simultâneos."}},"RL-032":{"cognitivo":{"motivo":"Cobrar o cálculo de montante em juros simples.","palavraCritica":"R$ 9.800"},"comentario":{"resolucao":"ERRADO. Os juros simples acumulados são J=8.000×0,02×10=1.600. O montante correto é 8.000+1.600=R$ 9.600, e não R$ 9.800 como afirmado.","fundamento":"Matemática financeira — juros simples.","macete":"J = C×i×t (taxa em decimal). Montante = Capital + Juros.","erroComum":"Errar a multiplicação ou confundir com juros compostos.","comoBancaPensa":"Troca o resultado correto por um valor numericamente próximo."}},"RL-033":{"cognitivo":{"motivo":"Cobrar o cálculo correto de média ponderada.","palavraCritica":"6,0"},"comentario":{"resolucao":"ERRADO. A média ponderada correta é (7×3+5×2)/(3+2) = 31/5 = 6,2, e não 6,0 como afirmado — o valor 6,0 corresponderia à média aritmética simples entre 7 e 5, que ignora os pesos.","fundamento":"Matemática — estatística básica (média ponderada).","macete":"Multiplique cada nota pelo peso, some tudo e divida pela soma dos pesos.","erroComum":"Calcular a média aritmética simples, esquecendo de ponderar pelos pesos.","comoBancaPensa":"Troca o resultado correto por um valor 'redondo' e tentador."}},"RL-034":{"cognitivo":{"motivo":"Cobrar a fórmula do termo geral da progressão aritmética.","palavraCritica":"130"},"comentario":{"resolucao":"ERRADO. O vigésimo termo é a20 = 4+(20−1)×7 = 4+133 = 137, e não 130 como afirmado.","fundamento":"Matemática — progressão aritmética (termo geral).","macete":"an = a1+(n−1)×r. Não esqueça de subtrair 1 de n.","erroComum":"Usar 20×7 em vez de 19×7 (esquecer o '−1' na fórmula).","comoBancaPensa":"Troca o resultado correto por um valor obtido com erro comum de fórmula."}},"RL-035":{"cognitivo":{"motivo":"Cobrar a aplicação do princípio fundamental da contagem.","palavraCritica":"20 combinações"},"comentario":{"resolucao":"ERRADO. Pelo princípio fundamental da contagem, o número total de duplas motorista-viatura é 4×6 = 24, e não 20 como afirmado.","fundamento":"Matemática — análise combinatória (princípio multiplicativo).","macete":"Etapas independentes: multiplique, nunca some, as possibilidades.","erroComum":"Somar 4+6=10 em vez de multiplicar, ou errar a conta de 4×6.","comoBancaPensa":"Troca o resultado correto por um número plausível, mas incorreto."}},"RL-036":{"cognitivo":{"motivo":"Cobrar a tabela-verdade da disjunção inclusiva.","palavraCritica":"falsa apenas quando ambas falsas"},"comentario":{"resolucao":"CERTO. Na tabela-verdade da disjunção inclusiva (∨), o único caso em que o resultado é falso é quando P e Q são ambas falsas; em todos os outros três casos (V-V, V-F, F-V), a disjunção é verdadeira.","fundamento":"Lógica proposicional — tabela-verdade dos conectivos (disjunção).","macete":"'Ou' (∨) inclusivo: basta uma ser verdadeira para o todo ser verdadeiro.","erroComum":"Confundir com o 'ou exclusivo' (XOR), que é falso quando ambas têm o mesmo valor.","comoBancaPensa":"Item de fixação sobre a tabela-verdade do conectivo mais básico."}},"RL-037":{"cognitivo":{"motivo":"Cobrar o princípio da inclusão-exclusão em conjuntos.","palavraCritica":"17"},"comentario":{"resolucao":"ERRADO. A união dos dois grupos é 35+28−10=53. Subtraindo do total de servidores (60−53), o número de servidores sem nenhum dos cursos é 7, e não 17 como afirmado.","fundamento":"Matemática — teoria dos conjuntos (princípio da inclusão-exclusão).","macete":"|A∪B| = |A|+|B|−|A∩B|; 'nenhum dos dois' = total − |A∪B|.","erroComum":"Esquecer de subtrair a interseção, inflando o número de 'sem nenhum curso'.","comoBancaPensa":"Troca o resultado correto por um valor obtido ao esquecer a subtração da interseção."}},"RL-038":{"cognitivo":{"motivo":"Cobrar a identificação e aplicação de um padrão recursivo.","palavraCritica":"127"},"comentario":{"resolucao":"CERTO. Confirmando a regra (termo anterior×2+1) em toda a sequência dada, o próximo termo é 63×2+1 = 127.","fundamento":"Matemática — sequências numéricas (relações de recorrência).","macete":"Teste a regra proposta em ao menos dois pares consecutivos antes de aplicá-la.","erroComum":"Aplicar apenas parte da regra (ex.: só multiplicar, esquecendo de somar 1).","comoBancaPensa":"Item de fixação sobre reconhecimento e aplicação de padrões recursivos."}},"RL-039":{"cognitivo":{"motivo":"Cobrar a compreensão de que percentuais opostos sucessivos não se cancelam sobre bases diferentes.","palavraCritica":"retornou exatamente"},"comentario":{"resolucao":"ERRADO. Após o desconto de 10%, o valor passa a R$ 180 (200×0,9). O acréscimo de 10% incide sobre essa nova base: 180×1,1=R$ 198 — valor final inferior ao original de R$ 200, e não igual a ele.","fundamento":"Matemática — porcentagem (efeito de percentuais sucessivos sobre bases distintas).","macete":"Desconto e aumento de mesmo percentual NUNCA se cancelam — o resultado final é sempre menor que o original.","erroComum":"Presumir que -X% seguido de +X% sempre retorna ao valor inicial.","comoBancaPensa":"Generaliza uma crença intuitiva comum, mas matematicamente incorreta, para induzir ao erro."}},"RL-040":{"cognitivo":{"motivo":"Fixar o critério que separa proposição de sentença aberta.","palavraCritica":"não admite valoração enquanto a variável não for determinada"},"comentario":{"resolucao":"CERTO. Proposição é a sentença declarativa que admite exatamente um valor lógico (V ou F), pelos princípios da não contradição e do terceiro excluído. 'x + 2 = 5' é sentença aberta: só se torna proposição quando x é determinado.","fundamento":"Lógica proposicional — proposição e sentença aberta.","macete":"Tem variável indefinida? Não é proposição.","erroComum":"Tratar sentença aberta como proposição.","comoBancaPensa":"Par correto para separar quem entendeu o critério de valoração."}},"RL-041":{"cognitivo":{"motivo":"O enunciado pede um subconjunto dos cumprimentos — só os que cruzam moças e rapazes.","palavraCritica":"entre moças e rapazes"},"comentario":{"resolucao":"CERTO. A pergunta restringe-se aos acenos ENTRE MOÇAS E RAPAZES, e não a todos os cumprimentos da festa. Cada uma das 20 moças acenou para cada um dos 18 rapazes, e pelo princípio multiplicativo são 20 x 18 = 360 acenos — superior a 350, o que confirma a assertiva. Repare que os apertos de mão entre rapazes e os acenos entre moças ficam de fora da conta por não serem 'entre moças e rapazes'; incluí-los é o erro típico. Não há divisão por 2 aqui, porque o aceno é ato de quem acena, e não encontro mútuo — se o enunciado pedisse pares distintos, a conta seria outra.","fundamento":"Princípio fundamental da contagem.","macete":"Leia o que está sendo contado antes de contar. 20 x 18 = 360.","erroComum":"Somar todos os cumprimentos da festa, ou dividir o produto por 2.","comoBancaPensa":"Fornece dados suficientes para várias contas e especifica em três palavras qual delas quer."}},"RL-042":{"cognitivo":{"motivo":"Probabilidade clássica com combinações — a ordem não importa, e é isso que fixa o denominador.","palavraCritica":"aleatoriamente duas"},"comentario":{"resolucao":"CERTO. Casos possíveis: escolher 2 entre 5 sem importar a ordem, ou seja, C(5,2) = 10. Casos favoráveis: escolher exatamente os 2 culpados, C(2,2) = 1. Logo P = 1/10. Confira pelo caminho da multiplicação de probabilidades, que costuma ser mais seguro: a chance de o primeiro escolhido ser culpado é 2/5; dado isso, a de o segundo também ser é 1/4; e (2/5) x (1/4) = 2/20 = 1/10. Os dois métodos coincidem porque ambos tratam a escolha como não ordenada. Usar arranjo no lugar de combinação daria 20 no denominador e 2 no numerador — mesma fração, desde que a alteração seja feita nos dois lados.","fundamento":"Probabilidade clássica; combinações.","macete":"Escolha sem ordem é combinação. C(5,2) = 10 casos possíveis.","erroComum":"Misturar arranjo no denominador com combinação no numerador.","comoBancaPensa":"Número pequeno e conta curta; o erro vem da modelagem, não da aritmética."}},"RL-043":{"cognitivo":{"motivo":"A contrapositiva exige inverter E negar os dois termos — e aqui um deles já vem negado.","palavraCritica":"não está mentindo"},"comentario":{"resolucao":"CERTO. Chame p = 'Paulo está mentindo' e m = 'Maria está mentindo'. A primeira proposição é p → ~m. A CONTRAPOSITIVA de A → B é ~B → ~A, sempre equivalente à original. Aplicando: ~(~m) → ~p, e pela dupla negação ~(~m) = m, o que dá m → ~p, isto é, 'Se Maria está mentindo, então Paulo não está mentindo' — exatamente a segunda proposição. A dificuldade do item está na dupla negação: como o consequente já era negativo, negá-lo o torna afirmativo, e quem aplica a regra mecanicamente escreve 'Se Maria NÃO está mentindo' e conclui, errado, que não há equivalência.","fundamento":"Lógica proposicional — equivalência pela contrapositiva; dupla negação.","macete":"Contrapositiva: inverte a ordem e nega os dois. Negar o que já é negativo devolve o afirmativo.","erroComum":"Esquecer a dupla negação e produzir uma contrapositiva errada.","comoBancaPensa":"Constrói a condicional com o consequente já negado, para que a regra só funcione com a dupla negação."}},"RL-044":{"cognitivo":{"motivo":"Negar o universal produz um EXISTENCIAL, não o universal contrário.","palavraCritica":"Todos"},"comentario":{"resolucao":"ERRADO. A negação de 'TODO A é B' é 'ALGUM A NÃO é B' — troca-se o quantificador universal pelo existencial e nega-se o predicado. A negação correta seria 'Pelo menos um não é igual perante a lei'. 'Todos são diferentes' não é a negação: é a proposição CONTRÁRIA, e a diferença é lógica, não de estilo — contrárias não podem ser ambas verdadeiras, mas podem ser ambas falsas, ao passo que uma proposição e sua negação têm sempre valores opostos. Se metade fosse tratada com igualdade e metade não, tanto 'todos são iguais' quanto 'todos são diferentes' seriam falsas, o que prova que a segunda não nega a primeira.","fundamento":"Lógica de predicados — negação de proposições categóricas.","macete":"Negar TODO dá ALGUM NÃO. Nunca dá NENHUM nem TODO o contrário.","erroComum":"Negar trocando o predicado por seu oposto, mantendo o quantificador universal.","comoBancaPensa":"Oferece a contrária, que soa como negação na linguagem comum."}},"RL-045":{"cognitivo":{"motivo":"Item de mesa redonda em que a banca NÃO usou permutação circular — vale mais pelo método do que pelo número.","palavraCritica":"mesa redonda"},"comentario":{"resolucao":"CERTO, e o caminho da banca merece ser reproduzido, porque é o que ela repete. Pela justificativa oficial: a primeira pessoa com restrição tem 6 lugares possíveis na mesa; fixada ela, a segunda pessoa com restrição não pode ocupar os dois lugares vizinhos nem o dela própria, restando 3 opções; as outras quatro pessoas se distribuem livremente, em 4! = 24 maneiras. Total: 6 x 3 x 24 = 432, superior a 400. Observe que a banca tratou os LUGARES COMO DISTINTOS — não aplicou permutação circular, que descontaria as rotações e daria 5! - 2 x 4! = 72. É uma escolha de modelagem que muda o resultado por um fator de 6, e é a da banca que vale na prova.","fundamento":"Princípio multiplicativo com restrição de adjacência (resolução oficial CEBRASPE).","macete":"Posiciona primeiro quem tem restrição, depois solta o resto: 6 x 3 x 4! = 432.","erroComum":"Aplicar permutação circular (5!) por ver 'mesa redonda' e chegar a 72.","comoBancaPensa":"Usa o cenário de mesa redonda sem exigir o tratamento circular — o enunciado pergunta por lugares, não por posições relativas."}},"RL-046":{"cognitivo":{"motivo":"Basta contar proposições simples e aplicar 2 elevado a n — o desafio é contar certo.","palavraCritica":"mais de 15"},"comentario":{"resolucao":"CERTO. Identifique as proposições SIMPLES: (1) o condenado é reincidente em crime doloso, (2) tem bons antecedentes, (3) cumpriu mais de um terço da pena e (4) pedirá o livramento condicional — quatro ao todo. O número de linhas da tabela-verdade é 2 elevado ao número de proposições simples, ou seja, 2⁴ = 16, que é mais de 15. Dois cuidados na contagem: o 'não' da primeira é operador de negação, e não uma quinta proposição; e os conectivos 'e' e 'se... então' também não contam. A estrutura completa é (~A ∧ B ∧ C) → D.","fundamento":"Lógica proposicional — tabela-verdade e número de linhas.","macete":"Conte só as proposições SIMPLES e faça 2 elevado a n. Negações não contam.","erroComum":"Contar a negação como proposição à parte, chegando a 32 linhas.","comoBancaPensa":"Fixa o limiar exatamente em 15, um a menos que o resultado, para que só quem conta certo acerte."}},"RL-047":{"cognitivo":{"motivo":"A condicional só é falsa num único arranjo — e esse arranjo determina os dois lados.","palavraCritica":"P for falsa"},"comentario":{"resolucao":"CERTO. A condicional A → B é FALSA em um único caso: antecedente VERDADEIRO e consequente FALSO. Todos os outros três arranjos a tornam verdadeira. Logo, dizer que P é falsa equivale a afirmar simultaneamente duas coisas: que o antecedente é verdadeiro (o condenado não é reincidente, tem bons antecedentes e cumpriu mais de um terço da pena) e que o consequente é falso (ele NÃO pedirá o livramento condicional). A assertiva afirma justamente a segunda, e por isso está correta. Este é o raciocínio de partida para negar condicionais: ~(A → B) equivale a A ∧ ~B — a negação de um 'se... então' nunca é outro 'se... então'.","fundamento":"Lógica proposicional — tabela-verdade da condicional; negação da condicional.","macete":"Condicional só é falsa com V → F. Negar 'se A então B' dá 'A e não B'.","erroComum":"Supor que P falsa torna também o antecedente falso.","comoBancaPensa":"Explora a única linha falsa da condicional, que a maioria decora sem entender."}},"RL-048":{"cognitivo":{"motivo":"Dois erros: 'nenhum' no lugar de 'algum não', e a disjunção que deveria virar conjunção.","palavraCritica":"nenhum"},"comentario":{"resolucao":"ERRADO, por dois motivos que se somam. Primeiro, negar 'TODO' produz 'ALGUM NÃO', jamais 'NENHUM' — 'nenhum' é a contrária, não a contraditória, como em RL-044. Segundo, ao negar o predicado é preciso aplicar De Morgan: a negação de 'brasileiro OU estrangeiro' é 'não brasileiro E não estrangeiro'. A negação correta, portanto, é: 'Pelo menos um condutor abordado não era brasileiro E não era estrangeiro'. O item erra no quantificador e ainda preserva o 'ou', que deveria ter virado 'e'.","fundamento":"Lógica de predicados; leis de De Morgan.","macete":"Nega TODO vira ALGUM NÃO; e ao negar, OU vira E.","erroComum":"Negar só o quantificador e deixar o predicado intacto.","comoBancaPensa":"Combina dois erros num só item, para que acertar exija dominar as duas regras."}},"RL-049":{"cognitivo":{"motivo":"Aplicação do princípio multiplicativo a um problema de segurança — arranjo COM repetição.","palavraCritica":"8 dígitos"},"comentario":{"resolucao":"CERTO. Cada uma das 8 posições admite qualquer algarismo de 0 a 9, com repetição permitida, e as escolhas são independentes. Pelo princípio multiplicativo, o total é 10 x 10 x ... x 10, oito vezes, ou seja, 10⁸ = 100 milhões de combinações. Note que se trata de ARRANJO COM REPETIÇÃO, e não de permutação ou combinação simples — o erro típico é usar fatorial. Do ponto de vista de segurança, o número ilustra por que senhas numéricas curtas são frágeis: 10⁸ é trivial para um atacante offline, e é por isso que se exige alfabeto ampliado (maiúsculas, minúsculas, símbolos), o que eleva a base de 10 para 90 e mais.","fundamento":"Princípio multiplicativo; arranjo com repetição.","macete":"n posições, k opções cada, com repetição: k elevado a n.","erroComum":"Usar fatorial ou combinação onde cabe arranjo com repetição.","comoBancaPensa":"Veste um problema de contagem com roupa de segurança da informação, tema que a PF cobra nas duas disciplinas."}},"RL-050":{"cognitivo":{"motivo":"Fixar a linha da tabela-verdade que mais gera dúvida e, ao mesmo tempo, apresentar termo absoluto em item VERDADEIRO.","palavraCritica":"sempre"},"comentario":{"resolucao":"CERTO. Na tabela-verdade de p → q, as duas linhas em que p é falso resultam em V, independentemente de q: F → V é verdadeira e F → F também é. Só existe uma linha falsa na condicional, aquela em que o antecedente é verdadeiro e o consequente é falso (V → F). Logo, antecedente falso implica condicional verdadeira, sempre.","fundamento":"Lógica proposicional — tabela-verdade da condicional.","macete":"A condicional só mente quando promete (V) e não cumpre (F). Antecedente falso não promete nada.","erroComum":"Marcar ERRADO por reflexo diante de 'sempre', sem conferir que a tabela-verdade autoriza a universalidade.","comoBancaPensa":"Item curto, categórico e VERDADEIRO — a contraprova exata de que 'termo absoluto = ERRADO' não é técnica."}},"RL-051":{"cognitivo":{"motivo":"Cobrar a tautologia p ∨ ~p com quantificação universal legítima.","palavraCritica":"sempre"},"comentario":{"resolucao":"CERTO. A fórmula p ∨ ~p é tautologia: se p é verdadeira, a disjunção é verdadeira pelo primeiro termo; se p é falsa, ~p é verdadeira e a disjunção é verdadeira pelo segundo. Não há linha da tabela-verdade em que resulte falsa. É o princípio do terceiro excluído.","fundamento":"Lógica proposicional — tautologia; princípio do terceiro excluído.","macete":"Ou chove ou não chove: uma das duas é verdade, sempre.","erroComum":"Confundir com a disjunção exclusiva, que também seria verdadeira aqui, mas por outra razão.","comoBancaPensa":"Afirmação universal e verdadeira, curta — formato que o candidato treinado a temer 'sempre' erra."}},"RL-052":{"cognitivo":{"motivo":"Cobrar o princípio da não contradição em enunciado com quantificador negativo universal.","palavraCritica":"Nenhuma"},"comentario":{"resolucao":"CERTO. É o princípio da não contradição, um dos fundamentos da lógica clássica: a proposição admite exatamente um valor lógico. A ressalva 'ao mesmo tempo e sob o mesmo aspecto' é a formulação clássica e afasta o falso contraexemplo de sentenças que mudam de valor conforme o contexto ou o momento.","fundamento":"Lógica proposicional — princípio da não contradição.","macete":"Proposição tem um valor só. Se parecer ter dois, mudou o tempo ou o aspecto.","erroComum":"Marcar ERRADO por 'Nenhuma', ou por lembrar de paradoxos que não são proposições no sentido clássico.","comoBancaPensa":"Negativa absoluta verdadeira — o espelho do item anterior e mais uma contraprova do reflexo."}},"RL-053":{"cognitivo":{"motivo":"Cobrar a definição de tautologia, que é universal por construção.","palavraCritica":"todas"},"comentario":{"resolucao":"CERTO. É a própria definição: tautologia é a proposição composta que resulta verdadeira para qualquer atribuição de valores às proposições simples que a compõem. Se houvesse uma única linha falsa, deixaria de ser tautologia e seria contingência.","fundamento":"Lógica proposicional — tautologia, contradição e contingência.","macete":"Tautologia: só V na coluna final. Contradição: só F. Contingência: mistura.","erroComum":"Estranhar dois quantificadores universais no mesmo enunciado e supor exagero.","comoBancaPensa":"Definição correta enunciada com 'toda' e 'todas' — dois gatilhos do reflexo numa frase só."}},"RL-054":{"cognitivo":{"motivo":"Cobrar a fórmula do conjunto das partes com quantificador universal legítimo.","palavraCritica":"Qualquer"},"comentario":{"resolucao":"CERTO. Cada elemento admite duas possibilidades independentes — pertencer ou não pertencer ao subconjunto —, o que dá 2 × 2 × … × 2 = 2^n combinações. Conferindo com n = 3: os subconjuntos de {a, b, c} são ∅, {a}, {b}, {c}, {a,b}, {a,c}, {b,c} e {a,b,c}, oito ao todo, e 2³ = 8.","fundamento":"Análise combinatória — conjunto das partes.","macete":"Cada elemento é uma chave liga-desliga. n chaves, 2^n combinações.","erroComum":"Esquecer de contar o vazio e o próprio conjunto, chegando a 2^n − 2.","comoBancaPensa":"Fórmula geral, verdadeira para qualquer n, apresentada com 'qualquer' e 'exatamente'."}},"RL-055":{"cognitivo":{"motivo":"Cobrar a definição de argumento sólido, distinguindo validade de veracidade.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"CERTO. Validade significa exatamente que é impossível ter todas as premissas verdadeiras e a conclusão falsa. Somando premissas de fato verdadeiras, a conclusão verdadeira decorre por necessidade — é o que se chama argumento sólido. Cuidado com a recíproca, que é falsa: um argumento válido pode ter conclusão falsa, desde que alguma premissa também seja falsa.","fundamento":"Lógica de argumentação — validade, verdade e solidez.","macete":"Válido = a forma preserva a verdade. Sólido = válido + premissas verdadeiras. Só o sólido garante conclusão verdadeira.","erroComum":"Rejeitar por 'necessariamente', quando a necessidade é justamente o que define a validade.","comoBancaPensa":"Duplo gatilho — 'todas' e 'necessariamente' — num item que é a definição correta."}},"RL-056":{"cognitivo":{"motivo":"Cobrar a regra de negação de quantificadores, com quantificação universal legítima sobre a própria regra.","palavraCritica":"sempre"},"comentario":{"resolucao":"CERTO. A negação de 'Todo A é B' é 'Algum A não é B' — basta um contraexemplo para derrubar a universal. Formalmente, ~(∀x)(A(x) → B(x)) equivale a (∃x)(A(x) ∧ ~B(x)). O erro clássico é negar para 'Nenhum A é B', que é a contrária, e não a contraditória.","fundamento":"Lógica de predicados — negação de quantificadores.","macete":"Nega o 'todo' com 'existe pelo menos um que não'. Nunca com 'nenhum'.","erroComum":"Negar 'Todo A é B' como 'Nenhum A é B', confundindo contrária com contraditória.","comoBancaPensa":"A regra é universal, e o item a enuncia com 'sempre' — verdadeiro, apesar do gatilho."}},"RL-057":{"cognitivo":{"motivo":"Cobrar probabilidade total, com resultado próximo do correto para punir a conta feita de cabeça.","palavraCritica":"40%"},"comentario":{"resolucao":"ERRADO. Pela probabilidade total: P = 0,60 × 0,25 + 0,40 × 0,50 = 0,15 + 0,20 = 0,35, ou seja, 35% — e não 40%. O erro de 5 pontos percentuais é exatamente o que se obtém ao trocar algum dos pesos, motivo pelo qual convém escrever as duas parcelas antes de somar.","fundamento":"Probabilidade — teorema da probabilidade total.","macete":"Probabilidade total = soma de (peso do grupo × taxa dentro do grupo). Escreva as parcelas separadas.","erroComum":"Somar as taxas e dividir por dois (37,5%) ou arredondar mentalmente para 40%.","comoBancaPensa":"Enunciado longo com dois grupos e duas taxas, e um resultado plausivelmente próximo do verdadeiro."}},"RL-058":{"cognitivo":{"motivo":"Cobrar permutação com elementos repetidos, com resultado errado por fator 2.","palavraCritica":"180"},"comentario":{"resolucao":"ERRADO. Trata-se de permutação de 6 elementos com três pares indistinguíveis: 6! / (2! × 2! × 2!) = 720 / 8 = 90 — e não 180. O valor 180 sai de dividir por apenas 4, isto é, de esquecer um dos três pares repetidos.","fundamento":"Análise combinatória — permutação com repetição.","macete":"Divida o fatorial total pelo fatorial de CADA grupo repetido. Conte os grupos antes de dividir.","erroComum":"Dividir por 2! duas vezes em vez de três, ou dividir por 3! por haver três categorias.","comoBancaPensa":"Contexto policial longo para consumir tempo, com resultado que é exatamente o dobro do correto."}},"RL-059":{"cognitivo":{"motivo":"Cobrar a não aditividade de variações percentuais sucessivas.","palavraCritica":"50%"},"comentario":{"resolucao":"ERRADO. Percentuais sucessivos multiplicam, não somam: 1,20 × 1,30 = 1,56, o que corresponde a 56% de crescimento acumulado, e não 50%. A diferença de 6 pontos é o efeito composto — os 30% de março incidem sobre uma base já 20% maior.","fundamento":"Porcentagem — variações percentuais sucessivas.","macete":"Transforme cada variação em fator (1 + i) e MULTIPLIQUE. Somar percentuais é o erro mais comum da matéria.","erroComum":"Somar 20% + 30% e responder 50%.","comoBancaPensa":"Enunciado longo e cenário simples, com a resposta intuitiva errada colocada como conclusão."}},"RL-060":{"cognitivo":{"motivo":"Testar a distinção entre contrapositiva (equivalente) e inversa (não equivalente).","palavraCritica":"bem como"},"comentario":{"resolucao":"ERRADO. A primeira equivalência está certa: 'Se não q, então não p' é a contrapositiva de 'Se p, então q', e contrapositiva é equivalente. A segunda está errada: 'Se não p, então não q' é a INVERSA, que não equivale à original. Como o item afirma as duas, o conjunto é falso — basta uma parte falsa para derrubar tudo.","fundamento":"Lógica proposicional — contrapositiva, recíproca e inversa.","macete":"Só a contrapositiva (nega e inverte a ordem) equivale. Recíproca e inversa, não.","erroComum":"Validar o item pela primeira equivalência, que é verdadeira, sem julgar a segunda.","comoBancaPensa":"Verdade + falso emendado, com o 'bem como' escondendo a segunda afirmação no fim do período."}},"RL-061":{"cognitivo":{"motivo":"Cobrar inclusão-exclusão, com erro por não subtrair a interseção.","palavraCritica":"nenhum dos dois"},"comentario":{"resolucao":"ERRADO. Pelo princípio da inclusão-exclusão, quem concluiu pelo menos um curso é 60 + 45 − 20 = 85. Logo, não concluíram nenhum: 100 − 85 = 15, e não 5. O valor 5 resulta de somar 60 + 45 = 105 e subtrair de 100 sem devolver a interseção contada duas vezes.","fundamento":"Teoria dos conjuntos — princípio da inclusão-exclusão.","macete":"|A ∪ B| = |A| + |B| − |A ∩ B|. Quem está nos dois foi contado duas vezes e precisa voltar uma.","erroComum":"Esquecer de subtrair a interseção, ou subtraí-la duas vezes.","comoBancaPensa":"Enunciado longo com três números, e a resposta errada é a que sai da conta feita rápido."}},"RL-062":{"cognitivo":{"motivo":"Cobrar o reconhecimento da falácia da afirmação do consequente em contexto policial verossímil.","palavraCritica":"válido"},"comentario":{"resolucao":"ERRADO. O argumento tem a forma 'p → q; q; logo p', que é a falácia da afirmação do consequente. A conclusão não decorre: as digitais poderiam estar no objeto por outra razão — tê-lo manuseado antes, em outro lugar. O modo válido seria negar o consequente ('p → q; ~q; logo ~p'), que é o modus tollens.","fundamento":"Lógica de argumentação — modus ponens, modus tollens e falácias formais.","macete":"Afirmar o consequente e negar o antecedente são as duas falácias clássicas. Válidos são afirmar o antecedente e negar o consequente.","erroComum":"Aceitar por a conclusão parecer razoável no contexto investigativo — validade é da forma, não do conteúdo.","comoBancaPensa":"Veste a falácia com um cenário policial plausível e avisa 'independentemente da plausibilidade', contando com o candidato ignorar o aviso."}},"RL-063":{"cognitivo":{"motivo":"Cobrar o complementar em item curto e correto, para povoar a faixa curta com CERTO.","palavraCritica":"não ocorrer"},"comentario":{"resolucao":"CERTO. A probabilidade do evento complementar é 1 menos a do evento: 1 − 0,3 = 0,7. A soma das probabilidades de um evento e do seu complementar é sempre 1, porque juntos esgotam o espaço amostral.","fundamento":"Probabilidade — evento complementar.","macete":"P(A) + P(não A) = 1. Sempre.","erroComum":"Nenhum frequente — o item existe para calibrar o perfil de comprimento do banco, não para pegar o candidato.","comoBancaPensa":"A prova real tem itens curtos e diretos como este; nosso banco quase não tinha."}},"RL-064":{"cognitivo":{"motivo":"Cobrar conversão de fração em porcentagem, em item curto e correto.","palavraCritica":"16%"},"comentario":{"resolucao":"CERTO. 40 / 250 = 0,16, ou seja, 16%. Conferindo pelo caminho inverso: 10% de 250 são 25, e 16% são 25 × 1,6 = 40.","fundamento":"Porcentagem — razão parte/todo.","macete":"Ache 10% primeiro (divida por 10) e monte o resto a partir dele.","erroComum":"Inverter a razão e calcular 250/40.","comoBancaPensa":"Item curto, verdadeiro e de conta fechada — perfil que faltava na disciplina."}},"RL-065":{"cognitivo":{"motivo":"Cobrar a primeira lei de De Morgan em item curto e correto.","palavraCritica":"ou"},"comentario":{"resolucao":"CERTO. É a lei de De Morgan: ~(p ∧ q) equivale a ~p ∨ ~q. Para que 'chove e faz frio' seja falsa, basta que uma das duas falhe — daí a disjunção. Negar para 'não chove e não faz frio' seria exigir que as duas falhem, o que é mais forte do que a negação.","fundamento":"Lógica proposicional — leis de De Morgan.","macete":"Negou o 'e', vira 'ou'; negou o 'ou', vira 'e'. E nega cada parte.","erroComum":"Manter a conjunção na negação, produzindo proposição mais forte que a correta.","comoBancaPensa":"Regra fundamental cobrada de forma direta, em item curto e verdadeiro."}},"RL-066":{"cognitivo":{"motivo":"Separar proposição simples de composta e de frase que não é proposição.","palavraCritica":"simples"},"comentario":{"resolucao":"GABARITO E. Proposição simples é oração declarativa que admite exatamente um valor — verdadeiro ou falso — e não traz conectivo ligando duas orações. A letra E cumpre os dois requisitos. As letras A, C e D têm conectivo (\"e\", \"se… então\", \"se e somente se\") e por isso são compostas. A letra B é interrogativa: não se pode dizer que uma pergunta é verdadeira ou falsa, logo não é proposição.","fundamento":"Proposição simples × composta; requisitos da proposição lógica.","macete":"Procure conectivo. Achou, é composta. Não achou, veja se dá para responder V ou F.","erroComum":"Aceitar pergunta ou exclamação como proposição por serem frases completas.","comoBancaPensa":"Mistura os dois modos de errar: composta disfarçada de simples e frase não declarativa."}},"RL-067":{"cognitivo":{"motivo":"Introduzir a sentença aberta, que é declarativa mas não é proposição.","palavraCritica":"Ele"},"comentario":{"resolucao":"GABARITO E. \"Maria é auxiliar em saúde bucal\" é declarativa, sem conectivo, e pode ser julgada V ou F. A letra A é composta (tem \"e\"). A C é interrogativa e a D é exclamativa, e nenhuma das duas se valora. A letra B é a mais instrutiva: é declarativa, mas o pronome \"Ele\" não tem referente, de modo que não dá para dizer se é verdadeira — é SENTENÇA ABERTA, não proposição.","fundamento":"Proposição × sentença aberta; frases não declarativas.","macete":"Declarativa não basta. Se depende de saber quem é \"ele\" ou quanto vale \"x\", é sentença aberta.","erroComum":"Marcar B por ser afirmativa e ter sujeito e predicado.","comoBancaPensa":"Põe uma sentença aberta no meio das frases não declarativas, porque ela engana bem mais."}},"RL-068":{"cognitivo":{"motivo":"Reconhecer a composta pela presença do conectivo.","palavraCritica":"e"},"comentario":{"resolucao":"GABARITO E. Proposição composta é a formada pela junção de duas ou mais simples por conectivo lógico. Na letra E o \"e\" (conjunção, ∧) une \"Maria estudou\" e \"Antônio passou no teste\". As demais têm uma oração só, sem ligação lógica.","fundamento":"Proposição composta; conectivo de conjunção.","macete":"Duas orações com sujeito e verbo próprios, ligadas por conectivo: composta.","erroComum":"Confundir o \"e\" que liga orações com o \"e\" que só liga substantivos numa mesma oração.","comoBancaPensa":"Deixa quatro simples curtas e uma composta óbvia — item de aquecimento."}},"RL-069":{"cognitivo":{"motivo":"Repetir o reconhecimento da conjunção em posição diferente da lista.","palavraCritica":"e"},"comentario":{"resolucao":"GABARITO A. O \"e\" da letra A é o conectivo de conjunção (∧) ligando duas proposições simples. As outras quatro são orações únicas que admitem apenas V ou F, sem ligação lógica entre proposições.","fundamento":"Proposição composta; conjunção (∧).","macete":"Conte os verbos com sujeito próprio: dois ou mais com conectivo, é composta.","erroComum":"Achar que \"O verão será quente\" é composta por falar de futuro incerto — tempo verbal não cria conectivo.","comoBancaPensa":"Muda a posição da resposta na lista e mantém o resto do item, para pegar quem decorou a letra."}},"RL-070":{"cognitivo":{"motivo":"Reforçar a sentença aberta como armadilha central do tema.","palavraCritica":"Ele"},"comentario":{"resolucao":"GABARITO B. Para ser proposição a frase tem de ser declarativa e suportar valoração em V ou F. A letra A é interrogativa e a D é exclamativa: fora. A letra C é declarativa, mas o \"Ele\" sem referente a torna sentença aberta. Sobra a B, que afirma algo sobre pessoa identificada e pode ser julgada.","fundamento":"Requisitos da proposição lógica; sentença aberta.","macete":"Pergunta, ordem, desejo e exclamação nunca são proposição. Pronome solto também não.","erroComum":"Descartar B por \"bonita\" ser juízo subjetivo — subjetividade não impede valoração lógica.","comoBancaPensa":"Oferece uma proposição de conteúdo opinativo ao lado de uma sentença aberta bem construída."}},"RL-071":{"cognitivo":{"motivo":"Identificar o condicional entre outros conectivos e não proposições.","palavraCritica":"Se… então"},"comentario":{"resolucao":"GABARITO D. O condicional (→) aparece na linguagem natural como \"se… então…\" e variações. Só a letra D tem essa estrutura. Cuidado com a letra A: ela É proposição composta, mas o \"entretanto\" funciona como CONJUNÇÃO, não como condicional — o item pede o condicional especificamente. A B é proposição categórica com quantificador, a C é interrogativa e a E é imperativa.","fundamento":"Conectivo condicional (→); conjunções adversativas como conjunção lógica.","macete":"\"Entretanto\", \"mas\", \"porém\", \"contudo\": todos são o ∧ disfarçado.","erroComum":"Marcar A por ser a única outra composta da lista, sem ler que se pediu o condicional.","comoBancaPensa":"Coloca uma composta de conectivo diferente para punir quem só procura \"tem conectivo?\"."}},"RL-072":{"cognitivo":{"motivo":"Negar uma proposição que já vem na forma negativa.","palavraCritica":"não"},"comentario":{"resolucao":"GABARITO B. Negar uma proposição afirmativa é acrescentar o \"não\"; negar uma que já está negativa é RETIRÁ-LO. A proposição é ¬P, com P = \"Pedro é um mau pintor\". Sua negação é ¬(¬P) = P: \"Pedro é um mau pintor\". A letra A é a armadilha — \"bom\" não é a negação lógica de \"mau\", porque entre os dois cabe o pintor mediano.","fundamento":"Negação (¬) e dupla negação.","macete":"Negar não é achar o contrário: é dizer que aquilo não ocorre.","erroComum":"Trocar o adjetivo pelo seu antônimo em vez de remover a partícula de negação.","comoBancaPensa":"Oferece o antônimo como distrator principal — funciona quase sempre."}},"RL-073":{"cognitivo":{"motivo":"Traduzir símbolo a símbolo, sem pular a negação de nenhuma parcela.","palavraCritica":"∨"},"comentario":{"resolucao":"GABARITO D. Traduzindo por partes: ~P é \"ele NÃO cuida das nascentes\"; → é \"se… então\"; Q é \"ela cuida do meio ambiente\", SEM negação; ∨ é \"ou\"; ~R é \"eles NÃO gostam de acampar\". Montando: \"Se ele não cuida das nascentes, então ela cuida do meio ambiente ou eles não gostam de acampar\". Os distratores erram sempre em um de dois pontos: negam o Q que não está negado, ou trocam o \"ou\" por \"e\".","fundamento":"Tradução entre linguagem simbólica e natural; negação, condicional e disjunção.","macete":"Marque cada til no enunciado antes de ler as alternativas. Depois é só conferir quantos \"não\" cada uma tem.","erroComum":"Negar as duas parcelas do consequente por inércia, já que o antecedente veio negado.","comoBancaPensa":"Varia uma peça por vez entre as alternativas — só uma combinação bate."}},"RL-074":{"cognitivo":{"motivo":"Mostrar que proposição falsa continua sendo proposição, e que variável impede a valoração.","palavraCritica":"X"},"comentario":{"resolucao":"GABARITO A. O item I, \"2 × 2 = 6\", é declarativo e valorável: é FALSO — e ser falso não o desqualifica, proposição falsa é proposição. Os itens II e III trazem incógnitas cujo valor não se conhece, de modo que não há como dizer se são verdadeiros: são SENTENÇAS ABERTAS. Só o I é proposição.","fundamento":"Proposição × sentença aberta em contexto matemático.","macete":"Tem letra sem valor definido? Sentença aberta. Só números? Dá para julgar.","erroComum":"Descartar o item I por estar errado na conta, confundindo falsidade com não ser proposição.","comoBancaPensa":"Usa uma igualdade falsa como a única resposta certa, contando com o reflexo de \"errado = descarta\"."}},"RL-075":{"cognitivo":{"motivo":"Casar a palavra \"e\" com o símbolo da conjunção.","palavraCritica":"e"},"comentario":{"resolucao":"GABARITO C. O \"e\" é a conjunção, simbolizada pelo acento circunflexo ∧. Vale fixar a tabela inteira de uma vez: ∧ é \"e\"; ∨ é \"ou\" inclusivo; ⊻ é \"ou… ou\" exclusivo; → é \"se… então\"; ↔ é \"se e somente se\".","fundamento":"Simbologia dos conectivos lógicos.","macete":"∧ parece um A de \"And\". ∨ parece um V de \"Vel\", o \"ou\" latino.","erroComum":"Trocar ∧ por ∨ na hora da pressa — os dois são o mesmo desenho de cabeça para baixo.","comoBancaPensa":"Item de memorização pura; a única defesa é ter a tabela decorada."}},"RL-076":{"cognitivo":{"motivo":"Acrescentar a oração optativa ao rol das que não são proposição.","palavraCritica":"Que"},"comentario":{"resolucao":"GABARITO D. Só a letra D é oração declarativa completa, passível de julgamento em V ou F. As letras A e E são interrogativas; a B é imperativa (ordem); e a C é OPTATIVA — exprime desejo (\"Que o silêncio não prejudique…\"), e desejo não se julga verdadeiro nem falso. A D e a C falam quase a mesma coisa: a diferença está no modo verbal, não no assunto.","fundamento":"Modos oracionais que não constituem proposição: interrogativa, imperativa, exclamativa e optativa.","macete":"Compare a C com a D. Mesmo conteúdo, e só uma é proposição — o que decide é o modo verbal.","erroComum":"Ler a letra C como afirmação por ela começar com \"Que\" e não ter ponto de interrogação.","comoBancaPensa":"Coloca duas frases de conteúdo idêntico em modos diferentes, para isolar o critério."}},"RL-077":{"cognitivo":{"motivo":"Fixar que conteúdo falso não retira o caráter de proposição.","palavraCritica":"NÃO"},"comentario":{"resolucao":"GABARITO C. \"Faça a prova com calma!\" é imperativa: transmite ordem ou conselho, e não faz sentido chamá-la de verdadeira ou falsa. As letras A, B e D têm conteúdo empiricamente FALSO — o céu não é vermelho, motos não têm três rodas, o alfabeto não tem 23 letras —, e é exatamente por poderem ser julgadas falsas que elas SÃO proposições.","fundamento":"Oração imperativa; proposição falsa é proposição.","macete":"Falso é um dos dois valores possíveis. Quem tem valor, é proposição.","erroComum":"Marcar B ou D por notar que o conteúdo está errado.","comoBancaPensa":"Enche a lista de afirmações falsas para que o reflexo \"isso está errado\" atrapalhe."}},"RL-078":{"cognitivo":{"motivo":"Casar o símbolo ↔ com sua leitura em linguagem natural.","palavraCritica":"↔"},"comentario":{"resolucao":"GABARITO D. O ↔ é a bicondicional, lida como \"se, e somente se\". As demais alternativas percorrem os outros conectivos: a A lê como condicional (→), a B como disjunção inclusiva (∨), a C como conjunção (∧) e a E como disjunção exclusiva (\"ou… ou\", ⊻).","fundamento":"Conectivo bicondicional (↔).","macete":"A bicondicional é a seta de duas pontas: vale nos dois sentidos, por isso \"e somente se\".","erroComum":"Marcar A por ler a seta e pensar só em \"se… então\", sem notar a segunda ponta.","comoBancaPensa":"Oferece uma leitura para cada conectivo — item que testa a tabela de símbolos inteira."}},"RL-079":{"cognitivo":{"motivo":"Percorrer quatro conectivos numa tacada, pela palavra que os denuncia.","palavraCritica":"ou"},"comentario":{"resolucao":"GABARITO D. De cima para baixo: \"Maria E Paulo\" é conjunção (2); \"Maria NÃO recebe\" é negação (1); \"SE Paula…, ENTÃO…\" é condicional (4); \"Paulo OU Maria\" é disjunção (3). A sequência 2 – 1 – 4 – 3 corresponde à letra D. Em item de associação, o caminho mais rápido é fixar o primeiro par e eliminar tudo que não começa por ele — aqui, só A, C e D começam com 2.","fundamento":"Conectivos: negação, conjunção, disjunção e condicional.","macete":"Resolva o mais fácil primeiro e elimine. Raramente é preciso decidir os quatro.","erroComum":"Ler a Coluna 2 na ordem da Coluna 1, invertendo a associação.","comoBancaPensa":"Ordena a Coluna 2 fora da sequência da Coluna 1 justamente para punir a leitura paralela."}},"RL-080":{"cognitivo":{"motivo":"Traduzir adversativa gramatical em conjunção lógica.","palavraCritica":"mas"},"comentario":{"resolucao":"GABARITO D. Na lógica proposicional a conjunção não se limita à palavra \"e\". As adversativas do português — mas, porém, contudo, todavia, entretanto — cumprem a mesma função lógica, porque afirmam que as duas coisas ocorrem ao mesmo tempo: ela é dedicada E não chega em primeiro. A oposição de sentido é efeito estilístico, não muda a tabela-verdade.","fundamento":"Equivalência entre conjunções adversativas e o conectivo ∧.","macete":"Adversativa é ∧ de terno e gravata. A tabela-verdade é a mesma do \"e\".","erroComum":"Ver contraste entre as orações e procurar disjunção ou condicional.","comoBancaPensa":"Explora a distância entre a gramática, que separa aditiva de adversativa, e a lógica, que não separa."}},"RL-081":{"cognitivo":{"motivo":"Reforçar que proposição falsa é proposição, agora com conteúdo factual verificável.","palavraCritica":"Onde"},"comentario":{"resolucao":"GABARITO C. O item I é afirmativo e se pode julgar V ou F: é proposição. O item II também, e o fato de ser FALSO — Dilma Rousseff exerceu a presidência antes de 2018 — não o desqualifica, pelo contrário: só se pode chamar de falso o que tem valor lógico. O item III é interrogativo e não se valora. Logo, I e II.","fundamento":"Requisitos da proposição; frase interrogativa.","macete":"Pergunte \"posso responder V ou F a isso?\". Se a frase já é uma pergunta, a resposta é não.","erroComum":"Excluir o item II por saber que é factualmente falso.","comoBancaPensa":"Usa um fato notoriamente falso para testar se o candidato separa verdade de valorabilidade."}},"RL-082":{"cognitivo":{"motivo":"Classificar duas proposições em oposição direta.","palavraCritica":"Se… então"},"comentario":{"resolucao":"GABARITO C. O item I é uma oração declarativa única, sem conectivo: simples. O item II usa \"se… então\" para ligar \"fizer sol amanhã\" e \"vamos à praia\": composta, do tipo condicional. Item de duas variáveis e quatro combinações — basta acertar uma delas para eliminar metade das alternativas.","fundamento":"Proposição simples × composta; conectivo condicional.","macete":"Com duas proposições e quatro alternativas, classifique a mais óbvia e corte pela metade.","erroComum":"Contar \"Os cães são felizes\" como composta por ter sujeito plural.","comoBancaPensa":"Esgota as quatro combinações possíveis; não há como chutar por eliminação de absurdo."}},"RL-083":{"cognitivo":{"motivo":"Item de comando invertido sobre a tabela de símbolos.","palavraCritica":"INCORRETA"},"comentario":{"resolucao":"GABARITO B, que é a única falsa. O símbolo → REPRESENTA um conectivo lógico: é o condicional, \"se… então\". As letras C e D descrevem corretamente ∧ e ∨. A letra A também é verdadeira: \"Busco paz interior e felicidade\" tem o \"e\" ligando duas ideias, que a lógica lê como conjunção. Atenção ao comando — pediu-se a incorreta.","fundamento":"Simbologia dos conectivos: ∧, ∨, →.","macete":"Em item de comando invertido, marque com lápis quais são verdadeiras. Sobra uma.","erroComum":"Assinalar a letra C ou D, que estão certas, por ler o comando como \"assinale a correta\".","comoBancaPensa":"Põe três verdades óbvias e uma negação de fato elementar, apostando na desatenção ao comando."}},"RL-084":{"cognitivo":{"motivo":"Contar operadores numa frase longa, sem contar palavras que não são conectivo.","palavraCritica":"se, e somente se"},"comentario":{"resolucao":"GABARITO B. São quatro: \"se… então\" (condicional), \"se, e somente se\" (bicondicional), \"e\" (conjunção) e \"ou\" (disjunção). O erro típico é contar o \"se\" de \"se, e somente se\" separadamente, ou contar o \"e\" que está dentro dessa mesma expressão — os dois pertencem a um único conectivo, e quem os desmembra chega a seis.","fundamento":"Identificação e contagem de conectivos lógicos.","macete":"Sublinhe os conectivos INTEIROS antes de contar. \"Se, e somente se\" é uma peça só.","erroComum":"Contar as palavras \"se\", \"e\" e \"ou\" isoladamente e chegar a 6.","comoBancaPensa":"Escolhe uma frase em que uma expressão de três palavras contém dois falsos conectivos."}},"RL-085":{"cognitivo":{"motivo":"Traduzir conjunção com negação em apenas uma das parcelas.","palavraCritica":"∧"},"comentario":{"resolucao":"GABARITO B. A fórmula tem duas peças: p sem alteração, ligado por ∧ (\"e\") a ~q, que é q negado. Logo: \"O Brasil É um dos maiores exportadores\" E \"NÃO tem sistema econômico dependente do agronegócio\". A letra A esquece a negação; a C nega a parcela errada e troca o conectivo; a D mantém a negação certa mas troca ∧ por \"ou\".","fundamento":"Conjunção (∧) e negação (~) em tradução simbólica.","macete":"Confira duas coisas: qual parcela tem til e qual é o conectivo. Duas checagens resolvem.","erroComum":"Marcar D, que acerta a negação e erra o conectivo — é o distrator mais próximo.","comoBancaPensa":"Varia negação e conectivo de forma cruzada, para que nenhum acerto parcial baste."}},"RL-086":{"cognitivo":{"motivo":"Identificar o operador principal e agrupar corretamente o consequente.","palavraCritica":"então"},"comentario":{"resolucao":"GABARITO C. O operador PRINCIPAL é o condicional: \"se… então…\" separa a causa da consequência. A causa é p, \"desenvolvo o back-end\". A consequência tem duas ações simultâneas ligadas por \"e\": q, \"trabalha no front-end\", e r, \"diagrama o visual\". Como as duas juntas é que decorrem de p, elas ficam entre parênteses: p → (q ∧ r).","fundamento":"Simbolização de proposições compostas; operador principal e precedência.","macete":"Ache o \"então\". O que vem antes é o antecedente inteiro; o que vem depois, o consequente inteiro.","erroComum":"Escrever (p → q) ∧ r, jogando r para fora da implicação.","comoBancaPensa":"Dá alternativas com os mesmos símbolos e parênteses em posições diferentes."}},"RL-087":{"cognitivo":{"motivo":"Aplicar a equivalência adversativa/conjunção na direção da substituição.","palavraCritica":"substitua"},"comentario":{"resolucao":"GABARITO B. Adversativas — mas, porém, contudo, todavia, entretanto — operam como a conjunção \"e\", porque exigem que as duas sentenças ocorram simultaneamente. Trocar \"mas\" por \"e\" preserva a tabela-verdade: \"Caíque gosta de estudar E não gosta de fazer as tarefas\". Perde-se o contraste estilístico, que não é conteúdo lógico.","fundamento":"Equivalência entre adversativas e o conectivo ∧.","macete":"Se a frase afirma as duas coisas ao mesmo tempo, o conectivo é ∧, escreva-se como se escrever.","erroComum":"Escolher \"ou\", achando que a oposição de sentido pede alternativa entre as orações.","comoBancaPensa":"É a mesma equivalência da questão 15, agora cobrada na direção da troca."}},"RL-088":{"cognitivo":{"motivo":"Distinguir suficiente de necessária, e afastar as falácias da condicional.","palavraCritica":"suficiente"},"comentario":{"resolucao":"GABARITO A. Em p → q, o ANTECEDENTE é condição SUFICIENTE e o CONSEQUENTE é condição NECESSÁRIA. Aqui p é esforçar-se e q é vencer: basta esforçar-se para vencer, logo o esforço é suficiente. A letra B inverte os papéis. As letras C e D são a mesma falácia da negação do antecedente: de \"se p, então q\" não decorre \"se não p, então não q\" — pode-se vencer por outro caminho. A letra E nega o próprio condicional.","fundamento":"Condicional (→): condição suficiente × necessária; falácia da negação do antecedente.","macete":"Quem vem antes da seta BASTA (suficiente). Quem vem depois é EXIGIDO (necessário).","erroComum":"Marcar C, que soa como a leitura natural da promessa em português.","comoBancaPensa":"Oferece a inversão de papéis e a negação do antecedente, os dois erros mais frequentes do tema."}},"RL-089":{"cognitivo":{"motivo":"Reconhecer composta em que a segunda oração está elíptica.","palavraCritica":"e"},"comentario":{"resolucao":"GABARITO E. A letra E parece uma oração só porque o sujeito não se repete, mas traduzida por inteiro ela é \"(João é graduado) E (João é pós-graduado)\": duas proposições simples unidas por conjunção. As demais têm afirmação única, sem conectivo. Repare que a letra A tem \"nunca\", que é negação — e negação é operador unário, não liga duas proposições, então não torna a frase composta neste sentido.","fundamento":"Proposição composta com sujeito elíptico; conjunção.","macete":"Reescreva repetindo o sujeito. Se aparecerem duas frases completas, é composta.","erroComum":"Descartar a letra E por ver um sujeito só e nenhuma vírgula.","comoBancaPensa":"Esconde a segunda oração na elipse do sujeito, que é o disfarce mais eficiente da conjunção."}},"RL-090":{"cognitivo":{"motivo":"Distinguir tautologia (forma sempre verdadeira) de proposição apenas verdadeira.","palavraCritica":"Ou… ou"},"comentario":{"resolucao":"GABARITO C. Tautologia é a proposição cuja tabela-verdade dá V em todas as linhas, qualquer que seja o valor das simples. A letra C tem a forma P ⊻ ~P: a disjunção exclusiva exige valores diferentes nos dois lados, e P e ~P são sempre diferentes — resultado sempre V. As letras A e D são verdadeiras no mundo real, mas isso é contingência factual, não tautologia. A letra B é P ∧ ~P: contradição, sempre F. A letra E, (P ∧ Q) → ~P, dá F quando P e Q são verdadeiros.","fundamento":"Tautologia, contradição e contingência; princípio do terceiro excluído.","macete":"Tautologia é sobre a FORMA. Se você precisou saber geografia para responder, não era tautologia.","erroComum":"Marcar D por ser factualmente verdadeira — verdade de fato não é verdade lógica.","comoBancaPensa":"Coloca duas verdades empíricas na lista para capturar quem confunde verdadeiro com tautológico."}},"RL-091":{"cognitivo":{"motivo":"Item que só fecha com uma equivalência semântica assumida — e é justo dizê-lo.","palavraCritica":"inocente"},"comentario":{"resolucao":"GABARITO A, com uma ressalva que a banca não explicita. A resposta depende de aceitar que \"inocente\" significa exatamente \"não culpado\": só assim a frase vira P ∨ ~P, que é tautologia pela disjunção inclusiva — basta uma parcela verdadeira, e uma delas sempre é. Sem essa equivalência, \"culpado\" e \"inocente\" seriam duas proposições independentes e P ∨ Q seria contingência. A letra B é contradição sob a mesma leitura; a C é contingência entre pessoas diferentes; a D é ~P ∧ ~(~P), contradição.","fundamento":"Tautologia; disjunção inclusiva; princípio do terceiro excluído.","macete":"Quando o par de palavras é excludente e esgota as possibilidades, trate a segunda como negação da primeira.","erroComum":"Recusar a letra A por rigor — logicamente cabe a objeção, mas a banca cobra a leitura prática.","comoBancaPensa":"Usa antônimos do cotidiano como se fossem negação lógica; é preciso conhecer o hábito da banca."}},"RL-092":{"cognitivo":{"motivo":"Reconhecer a forma tautológica elementar sem montar a tabela inteira.","palavraCritica":"~P"},"comentario":{"resolucao":"GABARITO D. P ∨ ~P: se P é V, a primeira parcela basta e o total é V; se P é F, então ~P é V e o total é V de novo. Sempre V, logo tautologia. As demais dependem dos valores: P ∨ Q é F quando ambas são F; ~P ∨ Q é F com P verdadeira e Q falsa; P → Q é F com V→F; e P → ~P é F quando P é verdadeira. Todas contingências.","fundamento":"Tautologia; princípio do terceiro excluído (P ∨ ~P).","macete":"Decore as duas formas de cabeceira: P ∨ ~P é tautologia, P ∧ ~P é contradição.","erroComum":"Marcar P ∨ Q por lembrar que a disjunção \"é fácil de ser verdadeira\" — mas F ∨ F dá F.","comoBancaPensa":"Item de reconhecimento direto; quem monta as cinco tabelas perde tempo à toa."}},"RL-093":{"cognitivo":{"motivo":"Simplificar a fórmula antes de calcular, usando a dupla negação.","palavraCritica":"~(~P)"},"comentario":{"resolucao":"GABARITO B. Simplifique antes de montar tabela: ~(~P) é a dupla negação, que devolve P. O colchete vira P ∧ P, que é apenas P (idempotência). Sobra P ∨ ~P — a forma tautológica elementar, sempre verdadeira. Classificação: tautologia.","fundamento":"Dupla negação; idempotência da conjunção; tautologia.","macete":"Dois tis seguidos se cancelam. P ∧ P é P. Simplifique antes de calcular.","erroComum":"Montar a tabela de quatro linhas sem simplificar e errar um sinal no meio do caminho.","comoBancaPensa":"Infla a fórmula com operações que se anulam, para ver quem sabe reduzir."}},"RL-094":{"cognitivo":{"motivo":"Extrair valores do mundo real e aplicar a regra da condicional.","palavraCritica":"~b"},"comentario":{"resolucao":"GABARITO A. Primeiro os valores de fato: a é V (Lula foi presidente); b é F (a capital do Rio é a cidade do Rio de Janeiro), logo ~b é V; c é F (a Terra não é plana). Substituindo: (V ∧ V) → F, ou seja, V → F. A condicional é falsa exatamente nesse caso — e só nele. Logo D é falsa.","fundamento":"Tabela-verdade da condicional; negação.","macete":"A condicional só falha em V → F. Guardou isso, guardou a tabela inteira.","erroComum":"Esquecer de inverter b antes de aplicar, e calcular (V ∧ F) → F = F por outro caminho — resposta certa por raciocínio errado.","comoBancaPensa":"Escolhe fatos notórios para que o obstáculo seja a lógica, não o conhecimento geral."}},"RL-095":{"cognitivo":{"motivo":"Resolver de dentro para fora uma fórmula com três níveis de agrupamento.","palavraCritica":"↔"},"comentario":{"resolucao":"GABARITO C. Com p = V, r = V e q = F, resolva de dentro para fora. (p → q) = V → F = F. (r ∧ ~p) = V ∧ F = F. O colchete vira F → F, que é V — a condicional com antecedente falso é sempre verdadeira. ~q = V. Sobra V ↔ V, e a bicondicional com lados iguais dá V. Resultado: verdadeiro.","fundamento":"Condicional, conjunção, negação e bicondicional; ordem de resolução.","macete":"Bicondicional é teste de igualdade: lados iguais, V; lados diferentes, F.","erroComum":"Aplicar a regra V → F ao colchete sem perceber que ali o antecedente já virou F.","comoBancaPensa":"Aninha três níveis para que um erro no miolo contamine tudo — resolver de dentro para fora é obrigatório."}},"RL-096":{"cognitivo":{"motivo":"Percorrer a linha F/F em quatro conectivos de uma vez.","palavraCritica":"condicional"},"comentario":{"resolucao":"GABARITO E. Com as duas falsas: F → F é V, o que torna a letra E correta e a letra A errada, já que ambas falam do condicional e afirmam coisas opostas. F ↔ F é V, porque a bicondicional pede sinais iguais — a letra B diz que seria falso, errada. F ∧ F é F — a letra C errada. F ∨ F é F — a letra D errada.","fundamento":"Tabelas-verdade de →, ↔, ∧ e ∨ na linha F/F.","macete":"Na linha F/F só → e ↔ dão verdade. ∧ e ∨ dão falso.","erroComum":"Achar estranho que \"F → F\" seja verdadeiro e descartar a letra E por intuição.","comoBancaPensa":"Coloca a mesma afirmação em duas alternativas com finais opostos: uma delas é obrigatoriamente a resposta."}},"RL-097":{"cognitivo":{"motivo":"Fechar a linha F/F incluindo a disjunção exclusiva.","palavraCritica":"exclusiva"},"comentario":{"resolucao":"GABARITO C. Percorrendo a linha F/F: disjunção (F ∨ F) = F; conjunção (F ∧ F) = F; condicional (F → F) = V; bicondicional (F ↔ F) = V; disjunção exclusiva (F ⊻ F) = F, porque o \"ou… ou\" exige valores DIFERENTES para ser verdadeiro. Só III e IV preenchem a lacuna.","fundamento":"Tabelas-verdade na linha F/F; disjunção exclusiva.","macete":"Exclusiva é a do desempate: V só quando os lados discordam.","erroComum":"Incluir a exclusiva por confundi-la com a bicondicional — são exatamente opostas.","comoBancaPensa":"É a questão 31 em outro formato; quem entendeu a linha F/F resolve as duas em segundos."}},"RL-098":{"cognitivo":{"motivo":"Reconhecer a forma P → (P ∨ Q) sob linguagem natural.","palavraCritica":"ou"},"comentario":{"resolucao":"GABARITO A. A forma é P → (P ∨ Q). Se P é F, a condicional já é V. Se P é V, o consequente P ∨ Q contém P verdadeiro, e basta uma parcela verdadeira na disjunção — o consequente é V, e V → V dá V. Todos os caminhos levam a V: tautologia. As demais falham em algum ponto; a letra E, por exemplo, tem antecedente sempre verdadeiro (P ∨ ~P) e consequente livre, então é falsa quando Guilherme não é gordo.","fundamento":"Tautologia; condicional e disjunção inclusiva.","macete":"Se o consequente já contém o antecedente numa disjunção, a implicação não tem como falhar.","erroComum":"Marcar B, que troca ∨ por ∧ no consequente e deixa de ser tautologia.","comoBancaPensa":"Permuta \"e\"/\"ou\" e as posições de antecedente e consequente entre as cinco alternativas."}},"RL-099":{"cognitivo":{"motivo":"Classificar três fórmulas e perceber que uma delas se reduz a p.","palavraCritica":"(p → p)"},"comentario":{"resolucao":"GABARITO D. Item I, p → (p ∨ ¬q): com p falso, a condicional já é V; com p verdadeiro, o consequente contém p e é V, dando V → V. Tautologia. Item II, (p → p) → p: o parêntese p → p é sempre V, então a fórmula equivale a V → p, que vale exatamente o que p valer — verdadeira com p verdadeiro, falsa com p falso. CONTINGÊNCIA, e é aqui que a questão se decide. Item III, p → [(p → q) → q]: com p falso, V; com p verdadeiro, o colchete vira (V → q) → q, ou seja, q → q, que é V. Tautologia. Logo: tautológica, contingente, tautológica.","fundamento":"Tautologia, contradição e contingência; simplificação de fórmulas.","macete":"Nenhum dos três é contradição — logo, todas as alternativas com \"contraditória\" caem de saída. Restam A, D e E.","erroComum":"Chamar o item II de tautologia por ver p → p dentro dele, sem notar que a seta externa devolve p.","comoBancaPensa":"Repete \"contraditória\" em três alternativas sabendo que ninguém confere as três fórmulas."}},"RL-100":{"cognitivo":{"motivo":"Negar a classificação de simples diante de conectivo.","palavraCritica":"simples"},"comentario":{"resolucao":"ERRADO. O \"e\" liga duas proposições simples — \"João é alto\" e \"Maria é baixa\" —, o que faz da frase uma proposição COMPOSTA, do tipo conjunção (∧).","fundamento":"Proposição simples × composta; conjunção.","macete":"Achou conectivo, acabou a simplicidade.","erroComum":"Contar a frase como simples por ser curta e ter uma vírgula só.","comoBancaPensa":"Usa frases curtas com conectivo, porque tamanho engana mais que estrutura."}},"RL-101":{"cognitivo":{"motivo":"Confirmar os dois requisitos da proposição simples.","palavraCritica":"simples"},"comentario":{"resolucao":"CERTO. É oração declarativa, admite exatamente um valor lógico — no caso, verdadeiro — e não traz conectivo ligando orações. Cumpre os dois requisitos da proposição simples.","fundamento":"Proposição simples.","macete":"Declarativa + valorável + sem conectivo = simples.","erroComum":"Exigir que a proposição seja falsa ou duvidosa para \"merecer\" análise lógica.","comoBancaPensa":"Item de aquecimento; a mesma frase reaparece como distrator de tautologia na questão 25."}},"RL-102":{"cognitivo":{"motivo":"Mostrar que ser declarativa não basta.","palavraCritica":"pois"},"comentario":{"resolucao":"ERRADO. A premissa está certa — a frase é declarativa afirmativa —, mas a conclusão não segue. O pronome \"Ele\" não tem referente definido, de modo que não há como atribuir V ou F. É SENTENÇA ABERTA, não proposição. Sentença aberta vira proposição assim que a variável é preenchida.","fundamento":"Proposição × sentença aberta.","macete":"Se falta saber quem é \"ele\" ou quanto vale \"x\", falta o valor lógico.","erroComum":"Aceitar o item porque a justificativa dada é verdadeira.","comoBancaPensa":"Encadeia premissa correta e conclusão errada com um \"pois\" que parece fechar o raciocínio."}},"RL-103":{"cognitivo":{"motivo":"Excluir a exclamativa do rol de proposições.","palavraCritica":"valorada"},"comentario":{"resolucao":"ERRADO. \"Boa prova!\" é exclamativa: exprime desejo ou saudação, e não afirma nada que possa ser julgado verdadeiro ou falso. Não é proposição, e a justificativa do item é justamente o que lhe falta.","fundamento":"Frases não declarativas: interrogativa, imperativa, exclamativa e optativa.","macete":"Ponto de exclamação sozinho não decide, mas exclamação sem afirmação nunca é proposição.","erroComum":"Confundir frase completa com frase valorável.","comoBancaPensa":"Coloca no item a definição correta de proposição aplicada ao exemplo errado."}},"RL-104":{"cognitivo":{"motivo":"Confirmar composta por conjunção entre sujeitos distintos.","palavraCritica":"e"},"comentario":{"resolucao":"CERTO. Duas proposições simples com sujeitos próprios, unidas pelo conectivo de conjunção (∧). É o formato mais direto de proposição composta.","fundamento":"Proposição composta; conjunção.","macete":"Dois sujeitos, dois verbos, um conectivo: composta.","erroComum":"Nenhum relevante — item de fixação direta.","comoBancaPensa":"Alterna este formato com o de sujeito elíptico, que é bem mais difícil."}},"RL-105":{"cognitivo":{"motivo":"Negar composição onde há oração única.","palavraCritica":"composta"},"comentario":{"resolucao":"ERRADO. \"Chove agora\" é oração declarativa única, sem conectivo lógico. É proposição SIMPLES — e simples não deixa de sê-lo por ser curta ou por depender do momento em que se fala.","fundamento":"Proposição simples.","macete":"Sem conectivo, não há composição possível.","erroComum":"Ver o advérbio \"agora\" como segunda informação e contar duas proposições.","comoBancaPensa":"Testa se o candidato confunde informação adicional com proposição adicional."}},"RL-106":{"cognitivo":{"motivo":"Repetir a armadilha do pronome sem referente em outro enunciado.","palavraCritica":"Ele"},"comentario":{"resolucao":"ERRADO. Ser declarativa é necessário, mas não suficiente. Sem saber quem é \"Ele\", não há como julgar a frase verdadeira ou falsa: é sentença aberta. O mesmo vale para variáveis matemáticas não atribuídas.","fundamento":"Proposição × sentença aberta.","macete":"Pronome solto é a versão gramatical do \"x\" da equação.","erroComum":"Aceitar por ver sujeito, verbo e complemento no lugar.","comoBancaPensa":"Usa a mesma estrutura de armadilha em bancas diferentes — é padrão do tema, não de uma banca só."}},"RL-107":{"cognitivo":{"motivo":"Casar a estrutura \"se… então\" com o nome do conectivo.","palavraCritica":"condicional"},"comentario":{"resolucao":"CERTO. \"Se… então…\" é a forma canônica do conectivo condicional (→) na linguagem natural. Antecedente: \"Mario tem febre\". Consequente: \"deve permanecer internado por 48 horas\".","fundamento":"Conectivo condicional (→).","macete":"\"Se… então\", \"logo\", \"portanto\", \"implica\": todos são →.","erroComum":"Chamar de bicondicional por haver relação de causa e efeito nos dois sentidos no mundo real.","comoBancaPensa":"Cobra a nomenclatura exata do conectivo, não apenas a percepção de que há um."}},"RL-108":{"cognitivo":{"motivo":"Reconhecer a adversativa como conectivo de composição.","palavraCritica":"entretanto"},"comentario":{"resolucao":"CERTO. O \"entretanto\" liga duas proposições e funciona como CONJUNÇÃO lógica (∧): as duas coisas ocorrem ao mesmo tempo. A frase é composta. Cuidado para não classificá-la como condicional: adversativa não é \"se… então\".","fundamento":"Adversativas como conjunção lógica (∧).","macete":"Mas, porém, contudo, todavia, entretanto: cinco palavras, um só símbolo — o ∧.","erroComum":"Achar que o contraste de sentido cria disjunção, como se as orações se excluíssem.","comoBancaPensa":"Aproveita que a gramática separa aditiva de adversativa e a lógica não."}},"RL-109":{"cognitivo":{"motivo":"Aplicar a dupla negação em linguagem natural.","palavraCritica":"não"},"comentario":{"resolucao":"CERTO. A proposição é ¬P, com P = \"Pedro é um mau pintor\". Negá-la é ¬(¬P), que devolve P. Em linguagem natural: basta retirar a partícula \"não\".","fundamento":"Negação (¬) e dupla negação.","macete":"Negar quem já está negado é apagar o \"não\".","erroComum":"Procurar o antônimo do adjetivo em vez de mexer na negação.","comoBancaPensa":"Escolhe adjetivos com antônimo evidente (mau/bom) para tornar o desvio tentador."}},"RL-110":{"cognitivo":{"motivo":"Separar negação lógica de oposição semântica.","palavraCritica":"bom"},"comentario":{"resolucao":"ERRADO. Negar não é achar o contrário. A negação de \"Pedro não é um mau pintor\" é \"Pedro é um mau pintor\". Entre \"mau\" e \"bom\" cabe o pintor mediano: os dois adjetivos não esgotam as possibilidades, e por isso um não é a negação do outro.","fundamento":"Negação (¬); contrários × contraditórios.","macete":"Contraditórios não admitem meio-termo. Contrários admitem — e não servem como negação.","erroComum":"Tratar antônimos como negação, o que só funciona quando eles esgotam o universo.","comoBancaPensa":"É o distrator principal do tema de negação, e funciona na maioria das provas."}},"RL-111":{"cognitivo":{"motivo":"Conferir peça por peça a tradução simbólica.","palavraCritica":"∨"},"comentario":{"resolucao":"CERTO. Confira símbolo a símbolo: ~P vira \"ele NÃO cuida\"; → vira \"se… então\"; Q entra SEM negação; ∨ vira \"ou\"; ~R vira \"eles NÃO gostam\". A leitura do item bate exatamente.","fundamento":"Tradução entre linguagem simbólica e natural.","macete":"Conte os \"não\" da fórmula e os \"não\" da frase. Têm de ser o mesmo número, nas mesmas parcelas.","erroComum":"Negar o Q por inércia, porque o antecedente veio negado.","comoBancaPensa":"Erra sempre em uma peça só, o que torna a conferência item a item indispensável."}},"RL-112":{"cognitivo":{"motivo":"Separar ser falso de não ser proposição.","palavraCritica":"proposição"},"comentario":{"resolucao":"CERTO. A sentença é declarativa e admite exatamente um valor lógico: é FALSA. E só se pode chamar de falso aquilo que tem valor lógico — logo, é proposição. Estar errada na aritmética não a exclui da lógica.","fundamento":"Proposição em contexto matemático; falsidade × valorabilidade.","macete":"Falso é um valor. Sem valor nenhum é que não é proposição.","erroComum":"Descartar por conferir a conta e ver que não fecha.","comoBancaPensa":"Usa uma igualdade errada como resposta certa, contando com o reflexo do candidato."}},"RL-113":{"cognitivo":{"motivo":"Aplicar a sentença aberta ao contexto matemático.","palavraCritica":"X"},"comentario":{"resolucao":"ERRADO. Sem saber quanto vale X, não há como dizer se a igualdade é verdadeira ou falsa: é SENTENÇA ABERTA. Ela vira proposição no instante em que X recebe valor — com X = −2 é verdadeira, com qualquer outro é falsa.","fundamento":"Sentença aberta; variável livre.","macete":"Letra sem valor definido = sentença aberta, na matemática como na gramática.","erroComum":"Aceitar por ser uma equação bem formada e de aparência técnica.","comoBancaPensa":"Põe a sentença aberta ao lado de uma proposição falsa, para cobrar os dois conceitos de uma vez."}},"RL-114":{"cognitivo":{"motivo":"Fixar o símbolo da conjunção.","palavraCritica":"∧"},"comentario":{"resolucao":"CERTO. ∧ é a conjunção (\"e\"). A tabela completa: ∧ é \"e\"; ∨ é \"ou\" inclusivo; ⊻ é \"ou… ou\" exclusivo; → é \"se… então\"; ↔ é \"se e somente se\"; ~ ou ¬ é a negação.","fundamento":"Simbologia dos conectivos lógicos.","macete":"∧ tem a forma de um A — de And.","erroComum":"Inverter ∧ e ∨, que são o mesmo desenho espelhado.","comoBancaPensa":"Memorização pura; costuma vir junto com a leitura em linguagem natural."}},"RL-115":{"cognitivo":{"motivo":"Testar a inversão entre os dois símbolos espelhados.","palavraCritica":"∧"},"comentario":{"resolucao":"ERRADO. O \"ou\" inclusivo é ∨. O símbolo ∧ é a conjunção, o \"e\". A troca entre os dois é o erro mais comum do tema porque eles são graficamente espelhados.","fundamento":"Simbologia: ∧ (conjunção) × ∨ (disjunção inclusiva).","macete":"∨ vem de \"vel\", o \"ou\" do latim. ∧ vem de \"and\".","erroComum":"Trocar os dois sob pressão de tempo, mesmo sabendo a diferença.","comoBancaPensa":"Apresenta a definição certa com o símbolo do vizinho."}},"RL-116":{"cognitivo":{"motivo":"Introduzir a oração optativa entre as não proposições.","palavraCritica":"Que"},"comentario":{"resolucao":"ERRADO. A frase é OPTATIVA: exprime desejo, e desejo não se julga verdadeiro nem falso. Compare com \"O silêncio não prejudica a concentração\", que é declarativa e é proposição — mesmo assunto, modo verbal diferente, resultado lógico oposto.","fundamento":"Oração optativa; modos que não constituem proposição.","macete":"Começou com \"Que…\" no sentido de tomara: é desejo, não afirmação.","erroComum":"Ler como afirmação por não haver ponto de interrogação nem exclamação.","comoBancaPensa":"Aproveita que a optativa é a menos lembrada das quatro exceções."}},"RL-117":{"cognitivo":{"motivo":"Excluir a imperativa do rol de proposições.","palavraCritica":"Faça"},"comentario":{"resolucao":"ERRADO. Orações imperativas — ordens, conselhos, pedidos, instruções — não são proposições, porque não faz sentido chamá-las de verdadeiras ou falsas. Um conselho pode ser bom ou ruim, nunca verdadeiro ou falso.","fundamento":"Oração imperativa.","macete":"Verbo no imperativo, fora da lógica proposicional.","erroComum":"Confundir frase com sentido completo e frase com valor de verdade.","comoBancaPensa":"É a exceção mais cobrada das quatro, e a de reconhecimento mais fácil."}},"RL-118":{"cognitivo":{"motivo":"Consolidar a distinção entre valorabilidade e verdade.","palavraCritica":"ainda que"},"comentario":{"resolucao":"CERTO. A frase é declarativa e cabe julgá-la — o julgamento dá FALSO, e isso confirma que é proposição. Só tem valor lógico o que é proposição; portanto, poder ser falsa é prova de que é.","fundamento":"Proposição falsa é proposição.","macete":"Se dá para dizer \"isso está errado\", é porque havia o que julgar.","erroComum":"Descartar por saber que motos têm duas rodas.","comoBancaPensa":"Enche o item de afirmações falsas para que o conhecimento de mundo atrapalhe a análise lógica."}},"RL-119":{"cognitivo":{"motivo":"Casar símbolo e leitura da bicondicional.","palavraCritica":"somente"},"comentario":{"resolucao":"CERTO. ↔ é a bicondicional, lida como \"se, e somente se\". Ela é verdadeira quando os dois lados têm o MESMO valor lógico, e falsa quando divergem — funciona como um teste de igualdade.","fundamento":"Conectivo bicondicional (↔).","macete":"Seta de duas pontas: vale nos dois sentidos. Lados iguais, verdade.","erroComum":"Ler só a primeira ponta e tratar como condicional simples.","comoBancaPensa":"Cobra o par símbolo/leitura, ou troca por outro conectivo da tabela."}},"RL-120":{"cognitivo":{"motivo":"Separar bicondicional de disjunção exclusiva, que são opostas.","palavraCritica":"exclusiva"},"comentario":{"resolucao":"ERRADO. ↔ é a bicondicional (\"se e somente se\"); a disjunção exclusiva é ⊻ (\"ou… ou\"). E as duas não são só símbolos diferentes: são tabelas OPOSTAS. A bicondicional é verdadeira com lados iguais; a exclusiva, com lados diferentes.","fundamento":"Bicondicional (↔) × disjunção exclusiva (⊻).","macete":"↔ premia a concordância. ⊻ premia a discordância.","erroComum":"Tratar as duas como parentes por ambas compararem os dois lados.","comoBancaPensa":"Explora justamente o par que se opõe ponto a ponto na tabela."}},"RL-121":{"cognitivo":{"motivo":"Reconhecer conjunção com sujeito composto.","palavraCritica":"e"},"comentario":{"resolucao":"CERTO. A frase equivale a \"(Maria é técnica eletricista) E (Paulo é técnico eletricista)\": duas proposições unidas por conjunção (∧). O sujeito composto esconde a estrutura, mas não a elimina.","fundamento":"Conjunção (∧); sujeito composto.","macete":"Distribua o predicado entre os sujeitos. Aparecendo duas frases, há conjunção.","erroComum":"Ver o \"e\" ligando dois nomes e concluir que não há conectivo lógico.","comoBancaPensa":"Alterna entre o \"e\" que liga orações e o que liga sujeitos — o efeito lógico é o mesmo."}},"RL-122":{"cognitivo":{"motivo":"Nomear corretamente o conectivo diante da palavra que o denuncia.","palavraCritica":"ou"},"comentario":{"resolucao":"ERRADO. O \"ou\" é a DISJUNÇÃO, não a condicional. A condicional aparece como \"se… então\" e suas variações. Aqui não há relação de antecedente e consequente: há alternativa entre duas proposições.","fundamento":"Disjunção (∨) × condicional (→).","macete":"\"Ou\" é disjunção. \"Se… então\" é condicional. A palavra entrega o conectivo.","erroComum":"Nomear o conectivo pelo sentido da frase em vez de pela palavra que o marca.","comoBancaPensa":"Em item de associação, troca dois nomes de lugar e mantém os outros dois corretos."}},"RL-123":{"cognitivo":{"motivo":"Traduzir adversativa em conjunção lógica.","palavraCritica":"mas"},"comentario":{"resolucao":"CERTO. O \"mas\" é adversativo na gramática e conjuntivo na lógica: a frase afirma as duas coisas simultaneamente — ela é dedicada E não chega em primeiro. A tabela-verdade é a mesma do \"e\"; o contraste é efeito de estilo, não de lógica.","fundamento":"Adversativas como conjunção (∧).","macete":"Mas, porém, contudo, todavia, entretanto — todos viram ∧.","erroComum":"Buscar disjunção porque as ideias parecem se opor.","comoBancaPensa":"É a distância entre gramática e lógica, e a banca volta a ela em toda prova."}},"RL-124":{"cognitivo":{"motivo":"Excluir a interrogativa, mesmo longa e técnica.","palavraCritica":"Onde"},"comentario":{"resolucao":"ERRADO. É interrogativa: pergunta não se valora em verdadeiro ou falso, pede resposta. O comprimento e o vocabulário técnico não mudam isso.","fundamento":"Frase interrogativa não é proposição.","macete":"Ponto de interrogação encerra a análise lógica.","erroComum":"Deixar-se impressionar pelo tamanho e pela formalidade da frase.","comoBancaPensa":"Alonga a interrogativa para que ela pareça, à primeira vista, uma afirmação técnica."}},"RL-125":{"cognitivo":{"motivo":"Reforçar que a falsidade factual não desqualifica a proposição.","palavraCritica":"Nenhuma"},"comentario":{"resolucao":"CERTO. É declarativa e pode ser julgada — e o julgamento dá FALSO, já que Dilma Rousseff exerceu a presidência antes de 2018. Ter valor lógico é o que define a proposição; qual é esse valor não importa para a classificação.","fundamento":"Proposição; valorabilidade × verdade.","macete":"A pergunta não é \"isso é verdade?\", é \"dá para responder V ou F?\".","erroComum":"Excluir por saber que a afirmação é historicamente falsa.","comoBancaPensa":"Escolhe um fato notório e recente, para que o candidato tropece no conteúdo."}},"RL-126":{"cognitivo":{"motivo":"Classificar duas proposições em contraste direto.","palavraCritica":"ao passo que"},"comentario":{"resolucao":"CERTO. A primeira é oração declarativa única, sem conectivo: simples. A segunda liga \"fizer sol amanhã\" e \"vamos à praia\" pelo conectivo condicional: composta.","fundamento":"Proposição simples × composta; condicional.","macete":"Conte conectivos. Zero, simples; um ou mais, composta.","erroComum":"Ver o plural \"os cães\" como pluralidade de proposições.","comoBancaPensa":"Contrasta os dois tipos no mesmo item para forçar a comparação."}},"RL-127":{"cognitivo":{"motivo":"Negar uma afirmação falsa sobre a tabela de símbolos.","palavraCritica":"não representa"},"comentario":{"resolucao":"ERRADO. O símbolo → representa, sim, um conectivo lógico: o CONDICIONAL, lido \"se… então\". É um dos cinco operadores básicos, ao lado de ~, ∧, ∨ e ↔.","fundamento":"Simbologia dos conectivos lógicos.","macete":"Cinco operadores básicos: ~, ∧, ∨, →, ↔. A seta está entre eles.","erroComum":"Hesitar por associar a seta à implicação matemática e não ao conectivo proposicional.","comoBancaPensa":"Nega um fato elementar em item de comando invertido, onde a desatenção já basta para errar."}},"RL-128":{"cognitivo":{"motivo":"Fixar a leitura da disjunção inclusiva.","palavraCritica":"ou"},"comentario":{"resolucao":"CERTO. ∨ é a disjunção inclusiva, lida como \"ou\". Ela é verdadeira quando ao menos uma das parcelas é verdadeira, e só falsa quando as duas são falsas — o \"ou\" da lógica admite que ambas ocorram.","fundamento":"Disjunção inclusiva (∨).","macete":"Inclusiva inclui os dois. Só o \"ou… ou\" exclusivo é que exclui.","erroComum":"Assumir que \"ou\" sempre exclui uma das alternativas, como no uso coloquial.","comoBancaPensa":"Cobra a leitura simples aqui e a diferença entre inclusiva e exclusiva noutro item."}},"RL-129":{"cognitivo":{"motivo":"Contar conectivos sem desmembrar expressões compostas.","palavraCritica":"quatro"},"comentario":{"resolucao":"CERTO. São quatro: \"se… então\" (condicional), \"se, e somente se\" (bicondicional), \"e\" (conjunção) e \"ou\" (disjunção). O erro típico é contar como conectivos independentes o \"se\" e o \"e\" que estão DENTRO da expressão \"se, e somente se\" — quem faz isso chega a seis.","fundamento":"Identificação e contagem de conectivos.","macete":"Sublinhe cada conectivo por inteiro antes de contar. \"Se, e somente se\" é uma peça só.","erroComum":"Contar palavras em vez de operadores.","comoBancaPensa":"Escolhe a frase justamente porque um conectivo contém dois falsos conectivos dentro de si."}},"RL-130":{"cognitivo":{"motivo":"Separar condicional de bicondicional pela expressão que as marca.","palavraCritica":"somente"},"comentario":{"resolucao":"ERRADO. \"Se, e somente se\" é a BICONDICIONAL (↔). O condicional (→) é \"se… então\". A palavra \"somente\" é o que acrescenta a segunda direção da implicação — sem ela, seria só condicional.","fundamento":"Condicional (→) × bicondicional (↔).","macete":"Achou \"somente se\"? Bicondicional. Só \"se… então\"? Condicional.","erroComum":"Ver o \"se\" inicial e classificar como condicional sem ler o resto da expressão.","comoBancaPensa":"Aproveita que as duas expressões começam igual."}},"RL-131":{"cognitivo":{"motivo":"Conferir conectivo e posição da negação.","palavraCritica":"∧"},"comentario":{"resolucao":"CERTO. Duas checagens resolvem: o conectivo é ∧, que vira \"e\"; e o til está apenas sobre q, que por isso entra negado, enquanto p entra como está. A tradução do item corresponde exatamente à fórmula.","fundamento":"Conjunção (∧) e negação (~) em tradução simbólica.","macete":"Confira duas coisas: o conectivo e em qual parcela está o til.","erroComum":"Aplicar a negação às duas parcelas, ou trocar \"e\" por \"ou\".","comoBancaPensa":"Cruza negação e conectivo nos distratores para que nenhum acerto pela metade baste."}},"RL-132":{"cognitivo":{"motivo":"Identificar o operador principal e o alcance dos parênteses.","palavraCritica":"então"},"comentario":{"resolucao":"ERRADO. A simbolização correta é p → (q ∧ r). O operador principal é o condicional: o \"então\" separa antecedente e consequente. O antecedente é só p; o consequente reúne q e r ligados por \"e\", e por isso vai entre parênteses. A fórmula do item joga p e q juntos no antecedente e usa \"ou\", que nem aparece na frase.","fundamento":"Simbolização; operador principal e precedência.","macete":"Ache o \"então\". Tudo antes é antecedente; tudo depois é consequente.","erroComum":"Distribuir os símbolos na ordem em que as palavras aparecem, sem olhar o agrupamento.","comoBancaPensa":"Mantém as mesmas letras e muda parênteses e conectivos entre as alternativas."}},"RL-133":{"cognitivo":{"motivo":"Aplicar a equivalência adversativa/conjunção na direção da troca.","palavraCritica":"sem alteração"},"comentario":{"resolucao":"CERTO. As duas versões afirmam que ambas as orações ocorrem, e a tabela-verdade é idêntica. O que se perde na troca é o contraste estilístico entre as ideias — informação retórica, não lógica.","fundamento":"Equivalência entre adversativas e ∧.","macete":"Se a frase afirma as duas coisas ao mesmo tempo, o conectivo é ∧, escreva-se como se escrever.","erroComum":"Recusar a troca por sentir que o sentido da frase muda — muda o tom, não o valor lógico.","comoBancaPensa":"Cobra a mesma equivalência ora identificando o conectivo, ora autorizando a substituição."}},"RL-134":{"cognitivo":{"motivo":"Fixar o antecedente como condição suficiente.","palavraCritica":"suficiente"},"comentario":{"resolucao":"CERTO. Em p → q, o antecedente é condição SUFICIENTE e o consequente é condição NECESSÁRIA. Aqui, basta esforçar-se para vencer — o esforço é suficiente. Não se diz que seja necessário: pode-se vencer por outro caminho.","fundamento":"Condicional (→); condição suficiente × necessária.","macete":"Antes da seta BASTA. Depois da seta é EXIGIDO.","erroComum":"Trocar os dois termos, que soam intercambiáveis em português corrente.","comoBancaPensa":"Explora um par de palavras que o uso cotidiano trata como sinônimos e a lógica não."}},"RL-135":{"cognitivo":{"motivo":"Negar a inversão dos papéis na condicional.","palavraCritica":"necessária"},"comentario":{"resolucao":"ERRADO. Os papéis estão invertidos. O esforço é o antecedente, logo é condição SUFICIENTE. A condição necessária é a vitória — ou seja, se você se esforçou e não venceu, a promessa foi quebrada. Dizer que o esforço é necessário significaria que sem ele não haveria vitória, o que a proposição não afirma.","fundamento":"Condicional (→); condição suficiente × necessária.","macete":"Necessária é a de trás: sem ela, a implicação cai.","erroComum":"Ler \"necessário\" no sentido comum de \"importante\" e aceitar.","comoBancaPensa":"Enuncia a mesma proposição em dois itens, um com cada termo, e só um está certo."}},"RL-136":{"cognitivo":{"motivo":"Expor a falácia da negação do antecedente.","palavraCritica":"decorre logicamente"},"comentario":{"resolucao":"ERRADO. Isso é a falácia da NEGAÇÃO DO ANTECEDENTE. De p → q não decorre ~p → ~q: a proposição garante que o esforço leva à vitória, mas nada diz sobre quem não se esforça — essa pessoa pode vencer por sorte, talento ou outro caminho. O que decorre de p → q é a contrapositiva ~q → ~p: se não venceu, é porque não se esforçou.","fundamento":"Condicional; contrapositiva; falácia da negação do antecedente.","macete":"Da condicional só decorre a CONTRAPOSITIVA: nega o de trás e inverte a ordem.","erroComum":"Aceitar por ser a leitura natural de promessas em português (\"se estudar, passa\" soa como \"só passa quem estuda\").","comoBancaPensa":"É a falácia mais cobrada do tema, e a que mais coincide com a intuição."}},"RL-137":{"cognitivo":{"motivo":"Reconhecer composta cuja segunda oração está elíptica.","palavraCritica":"e"},"comentario":{"resolucao":"CERTO. Traduzida por inteiro, a frase é \"(João é graduado) E (João é pós-graduado)\": duas proposições simples unidas por conjunção. O sujeito não se repete, mas está subentendido na segunda — a elipse é gramatical, não lógica.","fundamento":"Proposição composta com sujeito elíptico.","macete":"Reescreva repetindo o sujeito. Se saírem duas frases inteiras, é composta.","erroComum":"Classificar como simples por haver um sujeito e um verbo só na superfície.","comoBancaPensa":"A elipse do sujeito é o disfarce mais eficiente da conjunção."}},"RL-138":{"cognitivo":{"motivo":"Reconhecer a forma tautológica sob linguagem natural.","palavraCritica":"Ou… ou"},"comentario":{"resolucao":"CERTO. A forma é P ⊻ ~P. A disjunção exclusiva é verdadeira quando os dois lados têm valores DIFERENTES, e P e ~P sempre têm: um é verdadeiro e o outro é falso, necessariamente. Resultado sempre V, em qualquer linha da tabela — tautologia. Note que não é preciso saber nada sobre Joinville.","fundamento":"Tautologia; disjunção exclusiva; princípio do terceiro excluído.","macete":"Se você não precisou consultar o mundo para responder, provavelmente é tautologia.","erroComum":"Achar que depende de qual é a maior cidade de Santa Catarina.","comoBancaPensa":"Envolve a forma lógica em conteúdo geográfico para ver quem separa forma de fato."}},"RL-139":{"cognitivo":{"motivo":"Distinguir tautologia de contradição na mesma forma.","palavraCritica":"contradição"},"comentario":{"resolucao":"ERRADO. Sob aquela equivalência a forma é P ∨ ~P, que é TAUTOLOGIA, não contradição: a disjunção inclusiva exige ao menos uma parcela verdadeira, e uma delas sempre é. Contradição seria P ∧ ~P — \"Roberto é culpado e Roberto é inocente\" —, que é sempre falsa.","fundamento":"Tautologia × contradição; P ∨ ~P e P ∧ ~P.","macete":"P ∨ ~P sempre V. P ∧ ~P sempre F. Muda só o conectivo, inverte tudo.","erroComum":"Ver \"culpado\" e \"inocente\" na mesma frase e concluir que há contradição.","comoBancaPensa":"Usa o mesmo par de proposições e troca o conectivo entre as versões do item."}},"RL-140":{"cognitivo":{"motivo":"Fixar a forma tautológica de cabeceira.","palavraCritica":"∨"},"comentario":{"resolucao":"CERTO. Se P é verdadeiro, a primeira parcela já garante o V; se P é falso, então ~P é verdadeiro e o V vem da segunda. Não existe linha em que o resultado seja falso. É o princípio do terceiro excluído em forma simbólica.","fundamento":"Tautologia; princípio do terceiro excluído.","macete":"Duas formas para decorar: P ∨ ~P sempre verdadeira, P ∧ ~P sempre falsa.","erroComum":"Montar a tabela quando bastaria reconhecer a forma.","comoBancaPensa":"Cobra a forma simbólica num item e a mesma forma em linguagem natural noutro."}},"RL-141":{"cognitivo":{"motivo":"Negar a tautologia onde há uma linha falsa.","palavraCritica":"tautologia"},"comentario":{"resolucao":"ERRADO. P → Q é CONTINGÊNCIA: seu valor depende de P e Q. Ela é verdadeira em três das quatro linhas, mas falsa naquela em que P é verdadeiro e Q é falso — e uma única linha falsa já basta para não ser tautologia.","fundamento":"Tautologia × contingência; tabela da condicional.","macete":"Tautologia é 100% de V. Uma linha falsa derruba.","erroComum":"Confundir \"quase sempre verdadeira\" com tautologia.","comoBancaPensa":"Oferece a condicional como distrator por ela ser verdadeira na maioria das linhas."}},"RL-142":{"cognitivo":{"motivo":"Fixar a lei da dupla negação como ferramenta de simplificação.","palavraCritica":"equivale"},"comentario":{"resolucao":"CERTO. É a lei da dupla negação: negar duas vezes devolve a proposição original. Se P é verdadeiro, ~P é falso e ~(~P) volta a ser verdadeiro; se P é falso, o caminho inverso leva ao mesmo lugar. Serve para encurtar fórmulas antes de montar tabela.","fundamento":"Lei da dupla negação.","macete":"Dois tis seguidos se cancelam. Risque os dois e siga.","erroComum":"Deixar a dupla negação na fórmula e montar tabela maior do que o necessário.","comoBancaPensa":"Infla fórmulas com operações que se anulam para separar quem simplifica de quem calcula tudo."}},"RL-143":{"cognitivo":{"motivo":"Aplicar a única linha falsa da condicional.","palavraCritica":"→"},"comentario":{"resolucao":"ERRADO. Substituindo: b é falsa, logo ~b é VERDADEIRA. O antecedente (a ∧ ~b) vira (V ∧ V) = V. O consequente c é falso. Sobra V → F, que é a ÚNICA combinação em que a condicional é falsa. Logo a proposição é falsa, não verdadeira.","fundamento":"Tabela-verdade da condicional; negação.","macete":"A condicional só falha em V → F. É a única linha que importa decorar.","erroComum":"Esquecer de inverter b e calcular o antecedente como falso.","comoBancaPensa":"Coloca a negação sobre a proposição falsa, para que quem não inverter chegue ao resultado oposto."}},"RL-144":{"cognitivo":{"motivo":"Resolver de dentro para fora, com três níveis de agrupamento.","palavraCritica":"↔"},"comentario":{"resolucao":"CERTO. De dentro para fora: (p → q) = V → F = F. (r ∧ ~p) = V ∧ F = F. O colchete vira F → F, que é V — condicional com antecedente falso é sempre verdadeira. ~q = V. Sobra V ↔ V, e a bicondicional com lados iguais dá V.","fundamento":"Condicional, conjunção, negação e bicondicional; ordem de resolução.","macete":"Resolva sempre do parêntese mais interno para fora, anotando o valor de cada bloco.","erroComum":"Aplicar V → F ao colchete inteiro sem notar que ali o antecedente já virou F.","comoBancaPensa":"Aninha três níveis para que um erro no miolo contamine o resultado final."}},"RL-145":{"cognitivo":{"motivo":"Fixar a linha F/F da condicional, que contraria a intuição.","palavraCritica":"condicional"},"comentario":{"resolucao":"CERTO. F → F resulta em V. A condicional só é falsa quando o antecedente é verdadeiro e o consequente falso; em qualquer outra combinação ela é verdadeira. Com antecedente falso, a promessa não chegou a ser testada, e a lógica clássica a considera cumprida.","fundamento":"Tabela-verdade da condicional.","macete":"Antecedente falso, condicional verdadeira. Sempre, sem exceção.","erroComum":"Rejeitar por parecer estranho que duas falsidades produzam verdade.","comoBancaPensa":"É a linha mais contraintuitiva da tabela, e por isso a mais cobrada."}},"RL-146":{"cognitivo":{"motivo":"Contrastar a linha F/F da conjunção com a da condicional.","palavraCritica":"conjunção"},"comentario":{"resolucao":"ERRADO. F ∧ F resulta em FALSO. A conjunção só é verdadeira quando as DUAS parcelas são verdadeiras — é o conectivo mais exigente da tabela. Quem confunde esta linha com a da condicional erra as duas.","fundamento":"Tabela-verdade da conjunção (∧).","macete":"Conjunção é a mais exigente: V só com V e V.","erroComum":"Generalizar a regra da condicional (\"falso gera verdade\") para os outros conectivos.","comoBancaPensa":"Cobra a mesma linha F/F em conectivos diferentes, no mesmo item ou em itens vizinhos."}},"RL-147":{"cognitivo":{"motivo":"Fechar a linha F/F com o conectivo menos estudado.","palavraCritica":"exclusiva"},"comentario":{"resolucao":"ERRADO. F ⊻ F resulta em FALSO. A disjunção exclusiva exige valores DIFERENTES para ser verdadeira — é o \"ou… ou\" que não admite os dois ao mesmo tempo nem nenhum dos dois. Na linha F/F, só a condicional e a bicondicional dão verdade.","fundamento":"Tabela-verdade da disjunção exclusiva (⊻).","macete":"Exclusiva é o teste de diferença. Bicondicional é o teste de igualdade. São opostas.","erroComum":"Confundir exclusiva com bicondicional e responder V.","comoBancaPensa":"Inclui a exclusiva na lista justamente por ser a menos praticada das cinco."}},"RL-148":{"cognitivo":{"motivo":"Reconhecer que o consequente contém o antecedente numa disjunção.","palavraCritica":"ou"},"comentario":{"resolucao":"CERTO. A forma é P → (P ∨ Q). Se P é falso, a condicional já é verdadeira. Se P é verdadeiro, o consequente contém P numa disjunção, e basta uma parcela verdadeira — o consequente é verdadeiro, e V → V dá V. Não há linha falsa: tautologia, e nada depende de Guilherme.","fundamento":"Tautologia; condicional e disjunção inclusiva.","macete":"Se o consequente já contém o antecedente ligado por \"ou\", a implicação não tem como falhar.","erroComum":"Recusar por achar que a frase precisa de informação sobre Guilherme.","comoBancaPensa":"Troca \"ou\" por \"e\" no distrator vizinho, e aí deixa de ser tautologia."}},"RL-149":{"cognitivo":{"motivo":"Simplificar a fórmula e ver que ela se reduz a p.","palavraCritica":"(p → p)"},"comentario":{"resolucao":"ERRADO. É CONTINGÊNCIA. O parêntese p → p é sempre verdadeiro, então a fórmula equivale a V → p — que vale exatamente o que p valer. Com p verdadeiro dá V; com p falso, V → F dá F. Havendo uma linha falsa, não é tautologia.","fundamento":"Tautologia × contingência; simplificação de fórmulas.","macete":"Antecedente sempre verdadeiro faz a condicional valer o que o consequente valer.","erroComum":"Ver p → p dentro da fórmula e concluir que o todo é tautologia.","comoBancaPensa":"Esconde uma tautologia dentro de uma fórmula que não é tautologia — a parte engana sobre o todo."}}});
